/* grammar-data.js —— 英语语法学习卡数据源（离线可读）
 * window.GRAMMAR 数组，每篇语法点结构：
 *   id        : 英文标识
 *   title     : 中文标题
 *   explain   : 中文讲解（1~3 句）
 *   rules     : 要点数组
 *   examples  : 例句数组 [{en, cn}]
 *   quiz      : 随堂练习 [{q, options:[], answer, explain}]
 * 暴露全局 window.GRAMMAR，由 英语语法学习卡.html 加载。 */
window.GRAMMAR = [
  {"id":"be-verb","title":"be 动词（am / is / are）","explain":"be 动词用来说明人或物是什么、在哪里、怎么样。它有三种形式：am（我用）、is（他/她/它用）、are（你/我们/你们/他们用）。","rules":["I 后面用 am","he / she / it 单数后面用 is","you / we / they 后面用 are","be 动词后可接名词、形容词或地点"],"examples":[{"en":"I am a student.","cn":"我是学生。"},{"en":"She is happy.","cn":"她很开心。"},{"en":"They are at school.","cn":"他们在学校。"}],"quiz":[{"q":"选择正确的 be 动词：He ___ my brother.","options":["am","is","are","be"],"answer":"is","explain":"he 是单数第三人称，用 is。"},{"q":"We ___ good friends.","options":["am","is","are","be"],"answer":"are","explain":"we 是复数，用 are。"},{"q":"I ___ a boy.","options":["am","is","are","be"],"answer":"am","explain":"I 后面用 am。"}]},
  {"id":"plural","title":"名词单复数","explain":"名词表示人、动物、事物或地方。很多名词变复数时加 -s 或 -es；有些词变化不规则，需要单独记忆。","rules":["一般情况加 -s（cat → cats）","以 s / x / ch / sh 结尾加 -es（box → boxes）","辅音 + y 结尾，变 y 为 i 加 -es（baby → babies）","不规则：man → men，child → children，foot → feet"],"examples":[{"en":"two cats","cn":"两只猫"},{"en":"three boxes","cn":"三个盒子"},{"en":"two children","cn":"两个孩子"}],"quiz":[{"q":"box 的复数是？","options":["boxs","boxes","boxies","boxe"],"answer":"boxes","explain":"以 x 结尾加 -es。"},{"q":"child 的复数是？","options":["childs","childes","children","childer"],"answer":"children","explain":"child 是不规则变化，复数为 children。"},{"q":"baby 的复数是？","options":["babys","babies","babyes","babyies"],"answer":"babies","explain":"辅音+y 变 y 为 i 再加 -es。"}]},
  {"id":"article","title":"冠词 a / an / the","explain":"冠词放在名词前。a / an 表示'一个'（泛指），the 表示'这个/那个'（特指）。a 用于辅音音素前，an 用于元音音素前。","rules":["a 用在辅音开头的词前（a dog）","an 用在元音开头的词前（an apple）","the 用于双方都知道的特定事物","首次提到用 a/an，再次提到用 the"],"examples":[{"en":"I see a cat.","cn":"我看见一只猫。"},{"en":"I eat an egg.","cn":"我吃一个鸡蛋。"},{"en":"The cat is black.","cn":"这只猫是黑色的。"}],"quiz":[{"q":"填空：I have ___ apple.","options":["a","an","the","/"],"answer":"an","explain":"apple 以元音开头，用 an。"},{"q":"填空：___ sun is big.","options":["A","An","The","/"],"answer":"The","explain":"太阳是双方都知道的特定事物，用 the。"},{"q":"填空：She is ___ teacher.","options":["a","an","the","/"],"answer":"a","explain":"teacher 以辅音开头且泛指，用 a。"}]},
  {"id":"demonstrative","title":"指示代词 this / that / these / those","explain":"指示代词用来指出人或物。this / these 指近处，that / those 指远处；this / that 是单数，these / those 是复数。","rules":["this：这个（近处，单数）","that：那个（远处，单数）","these：这些（近处，复数）","those：那些（远处，复数）"],"examples":[{"en":"This is my book.","cn":"这是我的书。"},{"en":"Those are apples.","cn":"那些是苹果。"}],"quiz":[{"q":"指近处的复数，用？","options":["this","that","these","those"],"answer":"these","explain":"these 表示近处的复数。"},{"q":"指远处的单数，用？","options":["this","that","these","those"],"answer":"that","explain":"that 表示远处的单数。"}]},
  {"id":"present-simple","title":"一般现在时","explain":"一般现在时表示经常发生的动作或客观事实。主语是 he / she / it 时，动词要变成第三人称单数（加 -s 或 -es）。","rules":["表示习惯、事实、常态","I / you / we / they + 动词原形","he / she / it + 动词三单（-s / -es）","否定用 don't / doesn't，疑问用 do / does"],"examples":[{"en":"I like apples.","cn":"我喜欢苹果。"},{"en":"She reads books.","cn":"她读书。"},{"en":"The sun rises in the east.","cn":"太阳从东方升起。"}],"quiz":[{"q":"He ___ TV every evening.","options":["watch","watches","watching","watchs"],"answer":"watches","explain":"he 作主语，动词变三单加 -es。"},{"q":"They ___ soccer after school.","options":["play","plays","playing","plaies"],"answer":"play","explain":"they 是复数，用动词原形。"}]},
  {"id":"present-continuous","title":"现在进行时","explain":"现在进行时表示此刻正在发生的动作，结构为：am / is / are + 动词 -ing。","rules":["结构：be + 动词 -ing","表示此时此刻正在做","常配 now / look / listen 等词","末尾辅元辅要双写（run → running）"],"examples":[{"en":"I am reading.","cn":"我正在读书。"},{"en":"He is running now.","cn":"他现在正在跑。"}],"quiz":[{"q":"填空：She ___ (eat) an apple now.","options":["eats","is eating","eat","eating"],"answer":"is eating","explain":"现在进行时结构为 is + 动词-ing。"},{"q":"填空：They are ___ (play) soccer.","options":["play","plays","playing","playeing"],"answer":"playing","explain":"are 后接动词 -ing 形式。"}]},
  {"id":"past-simple","title":"一般过去时","explain":"一般过去时表示过去发生的动作。规则动词加 -ed，不规则动词有固定变化（如 go → went）。","rules":["规则动词加 -ed（play → played）","不规则动词需记忆（go → went, eat → ate）","常以 yesterday / last 引导时间","否定、疑问借助 did"],"examples":[{"en":"We played soccer.","cn":"我们踢了足球。"},{"en":"He went home.","cn":"他回家了。"}],"quiz":[{"q":"go 的过去式是？","options":["goed","went","gone","goes"],"answer":"went","explain":"go 是不规则动词，过去式为 went。"},{"q":"填空：I ___ (watch) a movie yesterday.","options":["watch","watches","watched","watching"],"answer":"watched","explain":"规则动词过去式加 -ed。"}]},
  {"id":"modal-can","title":"情态动词 can","explain":"can 表示'能、会'，后面接动词原形。可用来谈能力，也可表示请求许可。","rules":["can + 动词原形","否定 can't，疑问把 can 提前","表示能力（我会游泳）","表示请求许可（我能走吗）"],"examples":[{"en":"I can swim.","cn":"我会游泳。"},{"en":"Can you help me?","cn":"你能帮我吗？"}],"quiz":[{"q":"填空：She ___ sing very well.","options":["can","cans","is can","can to"],"answer":"can","explain":"can 后接动词原形，不加 s。"},{"q":"can 的否定形式是？","options":["cann't","can't","not can","no can"],"answer":"can't","explain":"can 的否定为 can't。"}]},
  {"id":"there-be","title":"there be 句型","explain":"there is / there are 表示'某处有某物'。is 接单数名词，are 接复数名词。","rules":["there is + 单数名词","there are + 复数名词","就近原则：最近的名词决定 is / are","否定 there isn't / aren't"],"examples":[{"en":"There is a book on the desk.","cn":"桌上有一本书。"},{"en":"There are many stars.","cn":"有许多星星。"}],"quiz":[{"q":"填空：There ___ a cat under the chair.","options":["is","are","be","am"],"answer":"is","explain":"a cat 是单数，用 is。"},{"q":"填空：There ___ three dogs.","options":["is","are","be","am"],"answer":"are","explain":"three dogs 是复数，用 are。"}]},
  {"id":"comparative","title":"形容词比较级","explain":"形容词用来描述名词。比较级用于两者比较，常在词尾加 -er，或在前面加 more。","rules":["短词加 -er（tall → taller）","以 e 结尾加 -r（nice → nicer）","辅音 + y 变 y 为 i 加 -er（happy → happier）","多音节词加 more（more beautiful）"],"examples":[{"en":"He is taller than me.","cn":"他比我高。"},{"en":"This book is more interesting.","cn":"这本书更有趣。"}],"quiz":[{"q":"tall 的比较级是？","options":["taller","more tall","tallest","tallier"],"answer":"taller","explain":"短词直接加 -er。"},{"q":"happy 的比较级是？","options":["happier","more happy","happyer","happiest"],"answer":"happier","explain":"辅音+y 变 y 为 i 再加 -er。"}]},
  {"id":"preposition","title":"介词 in / on / under / by","explain":"介词表示位置、方向、时间等关系。in / on / under / by 是最常见的方位介词。","rules":["in：在……里面","on：在……上面（接触表面）","under：在……下面","by：在……旁边 / 被（被动）"],"examples":[{"en":"The cat is in the box.","cn":"猫在盒子里。"},{"en":"The book is on the desk.","cn":"书在桌上。"}],"quiz":[{"q":"填空：The ball is ___ the chair（在椅子下面）.","options":["in","on","under","by"],"answer":"under","explain":"under 表示在下方。"},{"q":"填空：The milk is ___ the fridge.","options":["in","on","under","by"],"answer":"in","explain":"in 表示在容器里面。"}]},
  {"id":"personal-pronoun","title":"人称代词","explain":"人称代词用来代替人或物。作主语时用主格：I / you / he / she / it / we / they。","rules":["第一人称：I（我）/ we（我们）","第二人称：you（你 / 你们）","第三人称：he / she / it（他 / 她 / 它）/ they（他们）","主格作主语，宾格（me / him…）作宾语"],"examples":[{"en":"He is my friend.","cn":"他是我的朋友。"},{"en":"We are students.","cn":"我们是学生。"}],"quiz":[{"q":"填空：___ am a boy.","options":["I","He","We","You"],"answer":"I","explain":"第一人称单数主格用 I。"},{"q":"填空：___ are my parents.","options":["He","She","They","It"],"answer":"They","explain":"parents 是复数，用 they。"}]},
  {"id":"possessive-pronoun","title":"物主代词","explain":"物主代词表示'某人的'，如 my / your / his / her / our / their，后面必须接名词。","rules":["my（我的）/ your（你的）","his（他的）/ her（她的）","our（我们的）/ their（他们的）","后接名词：my book, their teacher"],"examples":[{"en":"This is my dog.","cn":"这是我的狗。"},{"en":"Their school is big.","cn":"他们的学校很大。"}],"quiz":[{"q":"填空：This is ___ book.","options":["I","me","my","mine"],"answer":"my","explain":"物主代词 my 后接名词 book。"},{"q":"填空：___ teacher is kind.","options":["They","Them","Their","Theirs"],"answer":"Their","explain":"their 是物主代词，后接名词 teacher。"}]},
  {"id":"yes-no-question","title":"一般疑问句","explain":"一般疑问句用 yes / no 回答，常把 be 动词、do / does / did 或 can 放到句首。","rules":["be 提前：Are you happy?","do / does 提前：Do you like apples?","can 提前：Can he swim?","回答用 Yes / No + 主语 + be / do / can"],"examples":[{"en":"Are you a student?","cn":"你是学生吗？"},{"en":"Do they play soccer?","cn":"他们踢足球吗？"}],"quiz":[{"q":"把 'You are tall.' 变疑问句，开头用？","options":["Do","Are","Can","Does"],"answer":"Are","explain":"有 be 动词时把 are 提前。"},{"q":"对 'Do you like apples?' 肯定回答是？","options":["Yes, I do.","Yes, I am.","Yes, I like.","No, I do."],"answer":"Yes, I do.","explain":"用 do 提问就用 do 回答。"}]},
  {"id":"imperative","title":"祈使句","explain":"祈使句用来表示请求、命令或建议，以动词原形开头，通常省略主语 you。","rules":["动词原形开头（Open the door.）","否定加 Don't（Don't run.）","礼貌可加 please","用来给指令或建议"],"examples":[{"en":"Please sit down.","cn":"请坐下。"},{"en":"Don't touch the dog.","cn":"不要碰那只狗。"}],"quiz":[{"q":"祈使句通常以什么开头？","options":["主语 you","动词原形","be 动词","to"],"answer":"动词原形","explain":"祈使句以动词原形开头。"},{"q":"填空：___ run in the classroom.","options":["Not","Don't","No","Doesn't"],"answer":"Don't","explain":"祈使句否定用 Don't 开头。"}]},
  {"id":"future","title":"将来时 will / be going to","explain":"将来时表示将要发生的动作，用 will + 动词原形，或 be going to + 动词原形（表计划）。","rules":["will + 动词原形（I will go.）","be going to 表计划（I am going to eat.）","常配 tomorrow / next 等时间词","will 也可表承诺或预测"],"examples":[{"en":"I will visit Grandma.","cn":"我将去看奶奶。"},{"en":"It is going to rain.","cn":"天要下雨了。"}],"quiz":[{"q":"填空：I ___ (help) you tomorrow.","options":["will help","helping","helped","helps"],"answer":"will help","explain":"将来时用 will + 动词原形。"},{"q":"填空：She is ___ (go) to read a book.","options":["will go","going","goes","went"],"answer":"going","explain":"be going to 结构中用 going。"}]},
  {"id":"present-perfect","title":"现在完成时","explain":"现在完成时表示过去发生且与现在有关的动作，结构为 have / has + 过去分词。常与 already、just、yet、for、since 搭配。","rules":["结构：have / has + 过去分词","I / you / we / they 用 have，he / she / it 用 has","强调动作对现在的影响，而非具体时间","常配 for（持续）和 since（自从）"],"examples":[{"en":"I have finished my homework.","cn":"我已经做完作业了。"},{"en":"She has lived here for years.","cn":"她已经在这里住了很多年。"}],"quiz":[{"q":"填空：He ___ (read) this book twice.","options":["has read","have read","read","reads"],"answer":"has read","explain":"he 用 has，后接过去分词 read。"},{"q":"现在完成时结构是？","options":["have/has + 原形","have/has + 过去分词","did + 原形","be + 动词-ing"],"answer":"have/has + 过去分词","explain":"现在完成时由 have/has 加过去分词构成。"}]},
  {"id":"countable-uncountable","title":"可数与不可数名词","explain":"名词分可数（如 apple、book）和不可数（如 water、rice）。可数名词有单复数，不可数名词没有复数，表示数量要用 a glass of、some 等量词。","rules":["可数名词有单复数（apple → apples）","不可数名词无复数（water、milk、rice）","不可数名词用 some / much / a cup of 等修饰","many 接可数，much 接不可数"],"examples":[{"en":"I want some water.","cn":"我想要一些水。"},{"en":"There are three apples.","cn":"有三个苹果。"}],"quiz":[{"q":"下列哪个是不可数名词？","options":["apple","book","water","dog"],"answer":"water","explain":"water 是液体，不可数。"},{"q":"填空：I drink two ___ of milk.","options":["glass","glasses","glasss","glassies"],"answer":"glasses","explain":"milk 不可数，用量词 glass 的复数 glasses。"}]},
  {"id":"adverb","title":"副词","explain":"副词用来修饰动词、形容词或其他副词，常说明'怎样、何时、哪里'。许多副词由形容词加 -ly 构成（quick → quickly）。","rules":["副词常修饰动词（run fast）","形容词 + -ly 变副词（slow → slowly）","表示方式、时间、地点、程度","一般放动词后或句末"],"examples":[{"en":"He runs quickly.","cn":"他跑得快。"},{"en":"She speaks quietly.","cn":"她安静地说话。"}],"quiz":[{"q":"quick 的副词是？","options":["quickly","quick","quikly","quicky"],"answer":"quickly","explain":"形容词加 -ly 构成副词。"},{"q":"副词通常用来修饰？","options":["名词","动词","代词","冠词"],"answer":"动词","explain":"副词主要修饰动词、形容词或副词。"}]},
  {"id":"conjunction-because","title":"连词 because / so","explain":"because 表示'因为'，用来说明原因；so 表示'所以'，表示结果。注意中文常'因为…所以…'连用，但英文一般不同时用 because 和 so。","rules":["because 引导原因状语从句","so 引导结果","because 和 so 不在一个句子里同时用","because 放原因前或后均可"],"examples":[{"en":"I stay home because it rains.","cn":"我待在家，因为下雨了。"},{"en":"It rained, so we stayed home.","cn":"下雨了，所以我们待在家。"}],"quiz":[{"q":"填空：He is happy ___ he got a gift.","options":["because","so","but","and"],"answer":"because","explain":"说明原因用 because。"},{"q":"英文中 because 和 so 能同句用吗？","options":["能","不能","有时能","总是能"],"answer":"不能","explain":"because 和 so 不在一个句子里同时出现。"}]},
  {"id":"wh-question","title":"特殊疑问句（wh- 问句）","explain":"特殊疑问句用 what / who / where / when / why / how 等提问，句首用疑问词，后接一般疑问句语序（有 be/do 时提前）。","rules":["what 问事物，who 问人","where 问地点，when 问时间","why 问原因，how 问方式","后接 do/does/did 或 be 动词提前"],"examples":[{"en":"What do you like?","cn":"你喜欢什么？"},{"en":"Where is the school?","cn":"学校在哪里？"}],"quiz":[{"q":"问'谁'用哪个词？","options":["what","who","where","when"],"answer":"who","explain":"who 用来提问人。"},{"q":"填空：___ is your birthday?（何时）","options":["What","Who","When","Where"],"answer":"When","explain":"问时间用 when。"}]},
  {"id":"passive","title":"被动语态（基础）","explain":"被动语态表示'某物被……'，结构为 be + 过去分词。当动作承受者更重要或不知道是谁做的时用被动。","rules":["结构：be + 过去分词","一般现在时：am / is / are + 过去分词","强调动作承受者而非执行者","by 引出动作执行者（可省略）"],"examples":[{"en":"The window is cleaned by me.","cn":"窗户被我擦干净了。"},{"en":"English is spoken worldwide.","cn":"英语在全世界被使用。"}],"quiz":[{"q":"被动语态结构是？","options":["be + 过去分词","have + 过去分词","do + 原形","be + 动词-ing"],"answer":"be + 过去分词","explain":"被动由 be 动词加过去分词构成。"},{"q":"填空：The book ___ (write) by Lucy.","options":["is written","writes","wrote","writing"],"answer":"is written","explain":"书被写，用 is + 过去分词 written。"}]},
  {"id":"preposition-time","title":"时间介词 in / on / at","explain":"时间介词表示'在何时'。in 用于年、月、季节；on 用于具体某天；at 用于具体时刻。","rules":["in + 年/月/季节（in July, in summer）","on + 具体某天（on Monday, on July 1st）","at + 具体时刻（at 7 o'clock, at noon）","固定搭配要记牢"],"examples":[{"en":"We go swimming in summer.","cn":"我们夏天去游泳。"},{"en":"The party is on Sunday.","cn":"聚会在星期天。"}],"quiz":[{"q":"填空：I get up ___ 7 o'clock.","options":["in","on","at","for"],"answer":"at","explain":"具体时刻用 at。"},{"q":"填空：My birthday is ___ May.","options":["in","on","at","by"],"answer":"in","explain":"月份前用 in。"}]},
  {"id":"some-any","title":"some 与 any","explain":"some 和 any 都表示'一些'，用于可数与不可数名词。some 多用于肯定句，any 多用于否定句和疑问句。","rules":["some 用于肯定句（I have some apples.）","any 用于否定句和疑问句（I don't have any.）","希望得到肯定答复时，疑问句也可用 some","两者都可接可数复数与不可数"],"examples":[{"en":"I have some milk.","cn":"我有一些牛奶。"},{"en":"Do you have any questions?","cn":"你有什么问题吗？"}],"quiz":[{"q":"否定句中用？","options":["some","any","many","much"],"answer":"any","explain":"否定句和疑问句常用 any。"},{"q":"填空：Would you like ___ water?","options":["any","some","many","few"],"answer":"some","explain":"希望得到肯定答复的委婉问句用 some。"}]},
  {"id":"preposition-place","title":"方位介词 in / on / under","explain":"方位介词表示'在哪里'。in 在……里，on 在……上（表面），under 在……下。","rules":["in + 里面（in the box）","on + 表面（on the desk）","under + 下方（under the bed）","描述物品位置要用对介词"],"examples":[{"en":"The cat is under the chair.","cn":"猫在椅子下面。"},{"en":"The book is on the table.","cn":"书在桌子上。"}],"quiz":[{"q":"填空：The ball is ___ the box.","options":["on","under","in","to"],"answer":"in","explain":"在盒子里面用 in。"},{"q":"填空：The shoes are ___ the bed.","options":["in","on","under","at"],"answer":"under","explain":"在床下用 under。"}]},
  {"id":"possessive","title":"名词所有格","explain":"名词所有格表示'……的'，单数加 's（Tom's），复数以 s 结尾加 '（the boys'），不以 s 结尾加 's（the children's）。","rules":["单数 + 's（Lucy's book）","复数 s 结尾 + '（the teachers' room）","复数非 s 结尾 + 's（children's toys）","表示所属关系"],"examples":[{"en":"This is Tom's dog.","cn":"这是汤姆的狗。"},{"en":"The students' desks are clean.","cn":"学生们的书桌很干净。"}],"quiz":[{"q":"填空：This is ___ (Lucy) pen.","options":["Lucys","Lucy's","Lucy","Lucys'"],"answer":"Lucy's","explain":"单数名词加 's 表所有格。"},{"q":"填空：The ___ (boys) room is big.","options":["boys","boys'","boy's","boys's"],"answer":"boys'","explain":"复数以 s 结尾，只加 '。"}]},
  {"id":"modal","title":"情态动词 can / must / should","explain":"情态动词表示能力、必要或建议，后接动词原形。can 表能力，must 表必须，should 表应该。","rules":["can + 原形（I can swim.）","must + 原形（You must stop.）","should + 原形（We should read.）","否定：can't / mustn't / shouldn't"],"examples":[{"en":"He can speak English.","cn":"他会说英语。"},{"en":"We should eat healthy food.","cn":"我们应该吃健康的食物。"}],"quiz":[{"q":"填空：You ___ wear a coat. It is cold.","options":["can","must","may","will"],"answer":"must","explain":"天冷必须穿外套，用 must。"},{"q":"填空：___ I help you?","options":["Must","Should","Can","Am"],"answer":"Can","explain":"请求帮助用 Can I help you?。"}]},
  {"id":"pronoun","title":"人称代词与物主代词","explain":"人称代词主格 I/you/he/she/it/we/they 作主语；宾格 me/him/her 等作宾语；形容词性物主代词 my/your/his 后接名词。","rules":["主格作主语（He reads.）","宾格作宾语（Help me.）","my/your/his/her 后接名词（my book）","名词性物主代词可单独用（mine）"],"examples":[{"en":"She is my friend.","cn":"她是我的朋友。"},{"en":"This book is mine.","cn":"这本书是我的。"}],"quiz":[{"q":"填空：___ am a student.","options":["I","Me","My","Mine"],"answer":"I","explain":"作主语用主格 I。"},{"q":"填空：This is ___ (he) dog.","options":["he","him","his","he's"],"answer":"his","explain":"后接名词用形容词性物主代词 his。"}]},
  {"id":"superlative","title":"形容词最高级","explain":"最高级用于三者或三者以上比较，表示'最……'。短词加 -est，多音节词前加 most，前面通常加 the。","rules":["the + 最高级（the tallest）","短词加 -est（tall→tallest）","以 e 结尾加 -st（nice→nicest）","多音节词加 most（most beautiful）"],"examples":[{"en":"He is the tallest boy.","cn":"他是最高的男孩。"},{"en":"This is the most interesting book.","cn":"这是最有趣的书。"}],"quiz":[{"q":"tall 的最高级是？","options":["tallest","most tall","taller","tall"],"answer":"tallest","explain":"短词直接加 -est。"},{"q":"beautiful 的最高级用？","options":["beautifullest","most beautiful","more beautiful","the beautiful"],"answer":"most beautiful","explain":"多音节词前加 most。"}]},
  {"id":"frequency","title":"频率副词","explain":"频率副词表示动作发生的频繁程度，常放在动词前（be 动词后）。always(总是) > usually(通常) > often(经常) > sometimes(有时) > never(从不)。","rules":["always 总是，never 从不","usually 通常，often 经常","sometimes 有时","放在实义动词前、be 动词后"],"examples":[{"en":"I always brush my teeth.","cn":"我总是刷牙。"},{"en":"He is often late.","cn":"他经常迟到。"}],"quiz":[{"q":"表示'从不'的是？","options":["always","usually","never","often"],"answer":"never","explain":"never 表示从不。"},{"q":"频率副词常放在？","options":["句末","动词前/be后","句首","名词后"],"answer":"动词前/be后","explain":"频率副词置于实义动词前、be 动词之后。"}]},
  {"id":"cardinal-ordinal","title":"数词：基数词与序数词","explain":"基数词表示数量（one, two, three…），序数词表示顺序（first, second, third…），序数词前常加 the。","rules":["基数词表数量（one, two）","序数词表顺序（first, second）","序数词前常加 the（the first）","one→first, two→second, three→third"],"examples":[{"en":"I have three apples.","cn":"我有三个苹果。"},{"en":"He is the first student.","cn":"他是第一个学生。"}],"quiz":[{"q":"'第三'的序数词是？","options":["three","third","threeth","thirds"],"answer":"third","explain":"three 的序数词是 third。"},{"q":"序数词前常加？","options":["a","an","the","/"],"answer":"the","explain":"序数词前通常加 the。"}]},
  {"id":"have-has","title":"have / has（拥有）","explain":"have/has 表示'有'。I/you/we/they 用 have，he/she/it 用 has。否定和疑问借助 do/does。","rules":["I/you/we/they + have","he/she/it + has","否定用 don't/doesn't have","疑问用 Do/Does ... have?"],"examples":[{"en":"I have a red bag.","cn":"我有一个红书包。"},{"en":"She has a cat.","cn":"她有一只猫。"}],"quiz":[{"q":"He ___ a new pen.","options":["have","has","having","haves"],"answer":"has","explain":"he 作主语用 has。"},{"q":"They ___ two dogs.","options":["have","has","haves","having"],"answer":"have","explain":"they 作主语用 have。"}]},
  {"id":"or-question","title":"选择疑问句","explain":"选择疑问句提供两个或以上选项，用 or 连接，不能用 yes/no 回答，读时 or 前升调、or 后降调。","rules":["用 or 连接选项","不能用 Yes/No 回答","or 前升调、or 后降调","回答要具体选择其中一项"],"examples":[{"en":"Do you want tea or coffee?","cn":"你要茶还是咖啡？"},{"en":"Is it red or blue?","cn":"它是红色还是蓝色？"}],"quiz":[{"q":"选择疑问句用哪个词连接选项？","options":["and","or","but","so"],"answer":"or","explain":"用 or 连接选项。"},{"q":"对选择疑问句的回答？","options":["Yes./No.","具体选一项","I don't know","Sorry"],"answer":"具体选一项","explain":"选择疑问句不能用 yes/no，要具体回答。"}]},
  {"id":"reflexive","title":"反身代词","explain":"反身代词表示'我自己、你自己……'，由人称代词加 self/selves 构成，可强调'本人'或作宾语。","rules":["myself/yourself/himself/herself","ourselves/yourselves/themselves","单数 -self，复数 -selves","可作宾语或强调主语"],"examples":[{"en":"I can do it myself.","cn":"我自己能做。"},{"en":"She hurt herself.","cn":"她伤到了自己。"}],"quiz":[{"q":"'他自己'是？","options":["himself","hisself","heself","himeself"],"answer":"himself","explain":"he 的反身代词是 himself。"},{"q":"'我们自己'是？","options":["ourself","ourselves","weself","ourselves's"],"answer":"ourselves","explain":"we 的复数反身代词是 ourselves。"}]},
  {"id":"exclamatory","title":"感叹句","explain":"感叹句表达强烈感情，用 What 或 How 开头。What 后接名词，How 后接形容词或副词，句末用感叹号。","rules":["What + (a/an) + 名词!","How + 形容词/副词!","句末用感叹号","表示惊喜、赞美等强烈感情"],"examples":[{"en":"What a cute dog!","cn":"多可爱的狗啊！"},{"en":"How beautiful!","cn":"多美啊！"}],"quiz":[{"q":"___ a big apple! 填？","options":["How","What","Which","Why"],"answer":"What","explain":"后接名词用 What。"},{"q":"___ beautiful the flower is! 填？","options":["What","How","Which","Where"],"answer":"How","explain":"后接形容词用 How。"}]},
  {"id":"modal-may","title":"情态动词 may / might","explain":"may 表示'可以（许可）'或'可能'，might 是 may 的过去式或更委婉的可能，后接动词原形。","rules":["may + 动词原形","表示请求许可（May I...?）","表示可能（It may rain.）","might 更委婉或表过去"],"examples":[{"en":"May I go out?","cn":"我可以出去吗？"},{"en":"It may rain today.","cn":"今天可能下雨。"}],"quiz":[{"q":"礼貌请求许可常用？","options":["May I...?","Am I...?","Do I...?","Can I not?"],"answer":"May I...?","explain":"礼貌请求许可用 May I...?"},{"q":"表示'可能'可用？","options":["may","must","should","can't"],"answer":"may","explain":"may 可表示可能性。"}]},
  {"id":"infinitive","title":"动词不定式 to do","explain":"动词不定式是 to + 动词原形，可作主语、宾语或目的状语，表示'去做某事'。","rules":["结构为 to + 动词原形","可作宾语（I want to go.）","表目的（to read books）","某些动词后必接 to do"],"examples":[{"en":"I want to eat an apple.","cn":"我想吃一个苹果。"},{"en":"He went to the park to play.","cn":"他去公园玩。"}],"quiz":[{"q":"动词不定式结构是？","options":["to + 原形","to + 过去式","ing 形式","原形"],"answer":"to + 原形","explain":"不定式是 to 加动词原形。"},{"q":"I want ___ (go) home. 填？","options":["go","to go","going","went"],"answer":"to go","explain":"want 后接 to do。"}]},
  {"id":"indefinite","title":"不定代词","explain":"不定代词指不特定的人或物，如 somebody(某人)、anybody(任何人)、nothing(没什么)、everything(一切)。","rules":["somebody/anybody 指人","something/anything 指物","nothing = not anything","复合词结尾 -body/-thing/-one"],"examples":[{"en":"Somebody is at the door.","cn":"有人在门口。"},{"en":"I have nothing to say.","cn":"我没什么可说的。"}],"quiz":[{"q":"'没什么'是？","options":["something","anything","nothing","everything"],"answer":"nothing","explain":"nothing 表示没什么。"},{"q":"'某人'是？","options":["anybody","somebody","nobody","everybody"],"answer":"somebody","explain":"somebody 指某人。"}]},
  {"id":"noun-pronouns","title":"名词性物主代词","explain":"名词性物主代词可单独使用，相当于'形容词性物主代词 + 名词'，如 mine(我的)、yours(你的)。","rules":["mine/yours/his/hers/ours/theirs","可单独作主语或表语","= 形容词性物主代词 + 名词","后面不再接名词（This is mine.）"],"examples":[{"en":"This book is mine.","cn":"这本书是我的。"},{"en":"Is this pen yours?","cn":"这支笔是你的吗？"}],"quiz":[{"q":"'我的（东西）'单独用是？","options":["my","mine","me","myself"],"answer":"mine","explain":"名词性物主代词 mine 可单独用。"},{"q":"'他们的（东西）'是？","options":["their","theirs","them","they"],"answer":"theirs","explain":"theirs 是名词性物主代词。"}]},
  {"id":"agreement","title":"主谓一致基础","explain":"主谓一致指主语和谓语动词在数上保持一致。单数主语用单数动词，复数主语用复数动词。","rules":["单数主语 + 单数动词","复数主语 + 复数动词","不可数名词作单数","and 连接两主语通常作复数"],"examples":[{"en":"The dog barks.","cn":"狗叫。"},{"en":"The cats sleep.","cn":"猫睡觉。"}],"quiz":[{"q":"The boy ___ (play) soccer. 填？","options":["play","plays","playing","played"],"answer":"plays","explain":"单数主语用单数动词 plays。"},{"q":"My father and mother ___ teachers. 填？","options":["is","am","are","be"],"answer":"are","explain":"and 连接两人作复数，用 are。"}]},
  {"id":"negative","title":"否定句","explain":"否定句表示'不……'。有 be 动词或情态动词时直接加 not；实义动词借助 don't / doesn't（第三人称单数用 doesn't，动词还原）。","rules":["be + not（is not = isn't）","情态 + not（can not = can't）","实义动词用 don't / doesn't","三单用 doesn't，后面动词用原形"],"examples":[{"en":"I don't like eggs.","cn":"我不喜欢鸡蛋。"},{"en":"She isn't happy.","cn":"她不高兴。"}],"quiz":[{"q":"He ___ (like) apples. 否定填？","options":["don't like","doesn't like","doesn't likes","don't likes"],"answer":"doesn't like","explain":"三单否定用 doesn't，后接动词原形。"},{"q":"be 动词否定：She ___ happy.","options":["isn't","don't","doesn't","no"],"answer":"isn't","explain":"be 动词否定直接加 not，is not = isn't。"}]},
  {"id":"past-continuous","title":"过去进行时","explain":"过去进行时表示过去某一时刻正在进行的动作，结构为 was / were + 动词 -ing。","rules":["结构：was / were + 动词 -ing","I / he / she / it 用 was","you / we / they 用 were","常配 at that time / when 等"],"examples":[{"en":"I was reading at 8 o'clock.","cn":"八点时我正在读书。"},{"en":"They were playing soccer.","cn":"他们正在踢足球。"}],"quiz":[{"q":"填空：He ___ (watch) TV at that time.","options":["was watching","were watching","watched","watches"],"answer":"was watching","explain":"he 用 was + 动词 -ing。"},{"q":"They ___ (play) outside. 过去进行填？","options":["was playing","were playing","played","plays"],"answer":"were playing","explain":"they 用 were + 动词 -ing。"}]},
  {"id":"irregular-verbs","title":"常见不规则动词","explain":"不规则动词的过去式不按加 -ed 规则变化，需要逐个记忆。下面是小学最常用的几组。","rules":["go → went, eat → ate","see → saw, take → took","come → came, give → gave","do → did, have → had"],"examples":[{"en":"I went to the park.","cn":"我去了公园。"},{"en":"She ate an apple.","cn":"她吃了一个苹果。"}],"quiz":[{"q":"go 的过去式是？","options":["goed","went","gone","goes"],"answer":"went","explain":"go 是不规则动词，过去式 went。"},{"q":"see 的过去式是？","options":["saw","seen","seeed","sees"],"answer":"saw","explain":"see 的过去式是 saw。"}]},
  {"id":"coordinate","title":"并列连词 and / but / or","explain":"并列连词用来连接地位相同的词、短语或句子。and 表并列或顺承，but 表转折，or 表选择或'否则'。","rules":["and：和、并且","but：但是（转折）","or：或者、否则","连接相同成分（词或句）"],"examples":[{"en":"I like apples and oranges.","cn":"我喜欢苹果和橘子。"},{"en":"He is young but strong.","cn":"他年轻但强壮。"}],"quiz":[{"q":"表示转折用？","options":["and","but","or","so"],"answer":"but","explain":"but 表示转折。"},{"q":"'或者'用哪个连词？","options":["and","but","or","for"],"answer":"or","explain":"or 表示选择。"}]},
  {"id":"how-many-much","title":"how many 与 how much","explain":"how many 问可数名词的数量（后接复数），how much 问不可数名词的数量，也可用来问价格。","rules":["how many + 可数复数","how much + 不可数名词","how much 也可问价格","答语用数词或量词"],"examples":[{"en":"How many books do you have?","cn":"你有多少本书？"},{"en":"How much water is there?","cn":"那里有多少水？"}],"quiz":[{"q":"问'多少苹果'用？","options":["How many","How much","How","What"],"answer":"How many","explain":"apples 是可数复数，用 how many。"},{"q":"问'多少钱'用？","options":["How many","How much","How","Which"],"answer":"How much","explain":"问价格用 how much。"}]},
  {"id":"it-usage","title":"it 的特殊用法","explain":"it 除了指物，还常用来指代天气、时间、距离等，此时 it 没有具体意思，只是句子的形式主语。","rules":["it 指天气（It is rainy.）","it 指时间（It is 3 o'clock.）","it 指距离（It is far.）","it 作形式主语（It is easy.）"],"examples":[{"en":"It is snowing.","cn":"正在下雪。"},{"en":"It is nine o'clock.","cn":"九点了。"}],"quiz":[{"q":"'下雨了'中 it 指？","options":["天气","时间","距离","人"],"answer":"天气","explain":"It is raining 中 it 指天气。"},{"q":"It is 5 o'clock. 中 it 指？","options":["天气","时间","距离","物"],"answer":"时间","explain":"此处 it 指时间。"}]},
  {"id":"short-answer","title":"简略回答","explain":"对一般疑问句作答时，常用简略回答：Yes / No + 主语 + be / do / can 等，前后要保持一致。","rules":["Yes, 主语 + be / do / can","No, 主语 + be / do / can + not","主语用代词（he / she / they）","be / do / can 与问句一致"],"examples":[{"en":"Are you tired? Yes, I am.","cn":"你累吗？是的，我累。"},{"en":"Does she like cats? No, she doesn't.","cn":"她喜欢猫吗？不，她不喜欢。"}],"quiz":[{"q":"对 'Do they play?' 否定简答是？","options":["No, they don't.","No, they aren't.","No, they do.","No, they not."],"answer":"No, they don't.","explain":"用 do 问用 do 答。"},{"q":"对 'Is he tall?' 肯定简答是？","options":["Yes, he is.","Yes, he does.","Yes, he's.","Yes, is he."],"answer":"Yes, he is.","explain":"用 is 问用 is 答。"}]},
  {"id":"capitalization","title":"字母大写规则","explain":"英语书写中，句首字母、单词 I、人名地名等专有名词的首字母都要大写。","rules":["句首字母大写","单词 I 永远大写","人名、地名首字母大写","星期、月份首字母大写"],"examples":[{"en":"I am Tom.","cn":"我是汤姆。"},{"en":"We go to Beijing on Monday.","cn":"我们周一去北京。"}],"quiz":[{"q":"哪个单词永远大写？","options":["a","i","the","and"],"answer":"i","explain":"单词 I（我）永远大写。"},{"q":"星期几的首字母应？","options":["小写","大写","可大可小","不大写"],"answer":"大写","explain":"星期、月份等专有名词首字母大写。"}]},
  {"id":"sentence-parts","title":"句子成分基础（主谓宾）","explain":"一个简单句常由'主语 + 谓语'构成，谓语说明动作或状态；及物动词后还可以带宾语。","rules":["主语：句子主角（谁 / 什么）","谓语：动作或状态（常含动词）","宾语：动作的承受者","主谓通常在前、宾语在后"],"examples":[{"en":"The cat sleeps.","cn":"猫（主语）睡觉（谓语）。"},{"en":"Tom eats an apple.","cn":"汤姆（主语）吃（谓语）苹果（宾语）。"}],"quiz":[{"q":"'Tom eats an apple.' 中 eats 是？","options":["主语","谓语","宾语","定语"],"answer":"谓语","explain":"eats 是动词，作谓语。"},{"q":"上句中 an apple 是？","options":["主语","谓语","宾语","状语"],"answer":"宾语","explain":"an apple 是动作的承受者，作宾语。"}]},
  {"id":"must","title":"情态动词 must（必须 / 禁止）","explain":"must 表示'必须'，后接动词原形；mustn't 表示'禁止、千万不要'。语气比 should 更强。","rules":["must + 动词原形（必须）","mustn't = 禁止 / 不要","不必用 needn't 或 don't have to","语气比 should 更强"],"examples":[{"en":"You must wear a seatbelt.","cn":"你必须系安全带。"},{"en":"You mustn't play with fire.","cn":"你千万不能玩火。"}],"quiz":[{"q":"'禁止'用？","options":["must","mustn't","should","can"],"answer":"mustn't","explain":"mustn't 表示禁止。"},{"q":"must 后接？","options":["动词原形","to do","ing","过去式"],"answer":"动词原形","explain":"must 后接动词原形。"}]},
  {"id":"telling-time","title":"时间表达","explain":"整点说'数字 + o'clock'；半点说'half past + 数字'；一刻钟用 'a quarter past / to'。","rules":["整点：... o'clock","半点：half past ...","过一刻：a quarter past","差一刻：a quarter to"],"examples":[{"en":"It's three o'clock.","cn":"三点整。"},{"en":"It's half past six.","cn":"六点半。"}],"quiz":[{"q":"'六点半'怎么说？","options":["six o'clock","half past six","a quarter past six","half to six"],"answer":"half past six","explain":"半点用 half past + 数字。"},{"q":"'三点整'怎么说？","options":["three past","three o'clock","half past three","a quarter to three"],"answer":"three o'clock","explain":"整点用 数字 + o'clock。"}]},
  {"id":"double-object","title":"双宾语（给某人某物）","explain":"有些动词（give、buy、pass、show）可以接两个宾语：一个指人（间接宾语），一个指物（直接宾语）。结构：动词 + 人 + 物，或 动词 + 物 + to/for + 人。","rules":["give/buy/pass/show 可接双宾语","结构：动词 + 人 + 物（Give me a book.）","也可：动词 + 物 + to/for + 人","指人先、指物后最常见"],"examples":[{"en":"Mum gave me a gift.","cn":"妈妈给了我一个礼物。"},{"en":"I bought him a pen.","cn":"我给他买了一支笔。"}],"quiz":[{"q":"'给我一本书'正确是？","options":["Give me a book.","Give a book me.","Give to me a book.","Give me to book."],"answer":"Give me a book.","explain":"双宾语结构：动词 + 人 + 物。"},{"q":"同义转换：Give me a book. = Give a book ___ me.","options":["to","for","with","on"],"answer":"to","explain":"物在前时用 to 引出人。"}]},
  {"id":"how-old-tall","title":"how 问年龄与身高","explain":"how 可以搭配不同词提问。how old 问年龄，how tall 问身高，how heavy 问体重。回答用数词加单位。","rules":["how old 问年龄（I am 9.）","how tall 问身高（I am 1.4 m.）","how heavy 问体重","回答用数词 + 单位"],"examples":[{"en":"How old are you? I am nine.","cn":"你几岁？我九岁。"},{"en":"How tall is he? He is 150 cm.","cn":"他多高？他一百五十厘米。"}],"quiz":[{"q":"问'你几岁'用？","options":["How tall","How old","How heavy","How many"],"answer":"How old","explain":"how old 问年龄。"},{"q":"问身高用？","options":["How old","How tall","How big","How much"],"answer":"How tall","explain":"how tall 问身高。"}]},
  {"id":"numbers-20","title":"两位数数词（20–99）","explain":"二十到九十的整十数：twenty, thirty, forty, fifty... ；两位数如 21 读作 twenty-one（十位与个位间用连字符）。","rules":["整十：twenty/thirty/forty/fifty","21 = twenty-one（加连字符）","35 = thirty-five","百：one hundred"],"examples":[{"en":"twenty-one","cn":"21"},{"en":"forty-five","cn":"45"}],"quiz":[{"q":"23 怎么读？","options":["twenty three","twenty-three","two-three","twentythird"],"answer":"twenty-three","explain":"两位数十位与个位间加连字符。"},{"q":"'四十'是？","options":["fourty","forty","fourtyy","fourti"],"answer":"forty","explain":"注意 forty 没有 u。"}]},
  {"id":"week-month","title":"星期与月份名称","explain":"一周七天和十二个月份的首字母都要大写。星期：Monday–Sunday；月份：January–December。","rules":["星期：Monday/Tuesday...Sunday","月份：January/February...December","首字母大写","缩写常取前三个字母（Mon.）"],"examples":[{"en":"We have PE on Monday.","cn":"我们周一有体育课。"},{"en":"My birthday is in October.","cn":"我的生日在十月。"}],"quiz":[{"q":"'星期三'是？","options":["Wendesday","Wednesday","Wensday","Wednesda"],"answer":"Wednesday","explain":"Wednesday 注意拼写。"},{"q":"'九月'是？","options":["Septembre","September","Septembar","Sepetmber"],"answer":"September","explain":"九月是 September。"}]},
  {"id":"could","title":"情态动词 could","explain":"could 是 can 的过去式，表示'过去能'；也可用于更礼貌的请求或委婉的可能，后接动词原形。","rules":["could 是 can 的过去式","表示过去的能力（I could swim.）","更礼貌的请求（Could you help me?）","后接动词原形"],"examples":[{"en":"When I was three, I could sing.","cn":"我三岁时就会唱歌。"},{"en":"Could you open the door?","cn":"你能开门吗？（更礼貌）"}],"quiz":[{"q":"Could you help me? 中 could 表示？","options":["过去能力","更礼貌请求","禁止","必须"],"answer":"更礼貌请求","explain":"疑问句用 could 更委婉礼貌。"},{"q":"can 的过去式是？","options":["caned","could","can't","coud"],"answer":"could","explain":"could 是 can 的过去式。"}]},
  {"id":"adj-order","title":"多个形容词顺序（基础）","explain":"当名词前有多个形容词时，通常按'大小/长短 + 颜色'的顺序排列，如 a big red ball。","rules":["先大小，后颜色（a small blue bag）","长短也在颜色前（a long white dress）","多个形容词不用 and 连接","顺序：大小/长短 + 颜色 + 名词"],"examples":[{"en":"a big red apple","cn":"一个大红苹果"},{"en":"a small black cat","cn":"一只小黑猫"}],"quiz":[{"q":"正确顺序：a ___ bag（红/小）","options":["red small","small red","small and red","red and small"],"answer":"small red","explain":"先大小后颜色。"},{"q":"'一条长白裙子'是？","options":["a white long dress","a long white dress","a long and white dress","white long dress"],"answer":"a long white dress","explain":"长短在颜色前。"}]},
  {"id":"something-good","title":"不定代词 + 形容词后置","explain":"something、anything、nothing 等不定代词后面接形容词时，形容词要放在后面，如 something good（好东西）。","rules":["形容词放不定代词后（something nice）","否定/疑问用 anything（anything wrong）","nothing 后也后置（nothing new）","不能写成 good something"],"examples":[{"en":"I want something sweet.","cn":"我想要点甜的东西。"},{"en":"Is there anything new?","cn":"有什么新消息吗？"}],"quiz":[{"q":"'好东西'正确是？","options":["good something","something good","something well","good thing"],"answer":"something good","explain":"形容词置于不定代词之后。"},{"q":"疑问句：Is there ___ wrong?","options":["something","anything","nothing","everything"],"answer":"anything","explain":"疑问句用 anything，形容词后置。"}]},
  {"id":"verb-phrase","title":"常见动词短语","explain":"动词常和介词或副词搭配成短语，意思固定，如 get up（起床）、go to bed（睡觉）、go to school（上学）。","rules":["get up 起床","go to bed 睡觉","go to school 上学","brush my teeth 刷牙"],"examples":[{"en":"I get up at seven.","cn":"我七点起床。"},{"en":"He goes to bed early.","cn":"他早睡。"}],"quiz":[{"q":"'起床'是？","options":["get up","get on","get to","get in"],"answer":"get up","explain":"get up 表示起床。"},{"q":"'上学'是？","options":["go to school","go school","go to home","go school to"],"answer":"go to school","explain":"上学用 go to school（home 前不加 to）。"}]},
  {"id":"both-either","title":"both...and 与 either...or","explain":"both...and 表示'两者都'，either...or 表示'要么…要么'。两者连接相同词性。","rules":["both A and B（两者都）","either A or B（两者择一）","连接相同成分","either...or 就近原则"],"examples":[{"en":"Both Tom and Lucy like music.","cn":"汤姆和露西都喜欢音乐。"},{"en":"Either tea or coffee is fine.","cn":"茶或咖啡都行。"}],"quiz":[{"q":"'两者都'用？","options":["both...and","either...or","neither...nor","not only"],"answer":"both...and","explain":"both...and 表示两者都。"},{"q":"'要么…要么'用？","options":["both...and","either...or","all...and","some...or"],"answer":"either...or","explain":"either...or 表示二选一。"}]},
  {"id":"would-like","title":"would like 想要","explain":"would like 比 want 更礼貌，表示'想要'，后接名词或 to do。疑问用 Would you like...? ","rules":["would like + 名词（I would like an apple.）","would like + to do（I would like to go.）","疑问：Would you like...?","比 want 更礼貌"],"examples":[{"en":"I would like some water.","cn":"我想要些水。"},{"en":"Would you like a cake?","cn":"你想来块蛋糕吗？"}],"quiz":[{"q":"比 want 更礼貌的'想要'是？","options":["will like","would like","want to","like to"],"answer":"would like","explain":"would like 更礼貌。"},{"q":"I would like ___ (eat) an ice cream. 填？","options":["eat","to eat","eating","ate"],"answer":"to eat","explain":"would like 后接 to do。"}]},
  {"id":"like-usage","title":"like 的用法","explain":"like 表示'喜欢'。后接名词（I like apples.）或动词 -ing（I like swimming.），也可接 to do。否定借助 don't / doesn't。","rules":["like + 名词（I like music.）","like + 动词-ing（I like reading.）","三单用 likes","否定用 don't/doesn't like"],"examples":[{"en":"I like orange juice.","cn":"我喜欢橙汁。"},{"en":"She likes drawing.","cn":"她喜欢画画。"}],"quiz":[{"q":"I like ___ (swim). 填？","options":["swim","swimming","swims","to swim"],"answer":"swimming","explain":"like 后接动词 -ing。"},{"q":"He ___ (like) apples. 填？","options":["like","likes","liking","to like"],"answer":"likes","explain":"三单用 likes。"}]},
  {"id":"prep-with-for","title":"介词 with 与 for","explain":"with 常表示'和…一起'或'用（工具）'；for 表示'为了、给、因为'。两个都是最常用的介词。","rules":["with：和…一起（with me）","with：用（工具）（cut with a knife）","for：为了/给（a gift for you）","for：因为（famous for）"],"examples":[{"en":"I play with my friend.","cn":"我和朋友玩。"},{"en":"This is a cake for you.","cn":"这是给你的蛋糕。"}],"quiz":[{"q":"'和我一起'用？","options":["with","for","to","of"],"answer":"with","explain":"with 表示和…一起。"},{"q":"'给你的礼物'用？","options":["with","for","on","at"],"answer":"for","explain":"for 表示给、为了。"}]},
  {"id":"wh-words","title":"疑问词组 what color / what time / which","explain":"特殊疑问句除了 what/who/where，还常用 what color（什么颜色）、what time（几点）、which（哪一个）等词组提问。","rules":["what color 问颜色","what time 问具体时刻","which 问'哪一个'","后接一般疑问句语序"],"examples":[{"en":"What color is your bag?","cn":"你的包是什么颜色？"},{"en":"What time do you go to bed?","cn":"你几点睡觉？"}],"quiz":[{"q":"问'什么颜色'用？","options":["What color","What time","Which","How"],"answer":"What color","explain":"what color 问颜色。"},{"q":"问'几点'用？","options":["What color","What time","When","Where"],"answer":"What time","explain":"what time 问具体时刻。"}]},
  {"id":"have-to","title":"have to（不得不）","explain":"have to 表示'不得不、必须'，强调客观需要。I/you/we/they 用 have to，he/she/it 用 has to；否定用 don't/doesn't have to。","rules":["have to + 动词原形","he/she/it 用 has to","否定 don't/doesn't have to","比 must 更侧重客观"],"examples":[{"en":"I have to do my homework.","cn":"我不得不做作业。"},{"en":"She has to go now.","cn":"她现在得走了。"}],"quiz":[{"q":"He ___ (have) to leave. 填？","options":["have","has","having","haves"],"answer":"has","explain":"he 用 has to。"},{"q":"否定：I ___ have to cry.","options":["don't","doesn't","am not","not"],"answer":"don't","explain":"否定用 don't have to。"}]},
  {"id":"lets","title":"Let's 提建议","explain":"Let's = Let us，用来提建议'让我们…吧'，后接动词原形。回答常用 OK / Great / All right。","rules":["Let's + 动词原形","表示建议'让我们…'","回答 OK / Great","否定 Let's not"],"examples":[{"en":"Let's go to the park.","cn":"我们去公园吧。"},{"en":"Let's read a book.","cn":"我们读本书吧。"}],"quiz":[{"q":"Let's ___ (play) soccer. 填？","options":["play","playing","to play","plays"],"answer":"play","explain":"Let's 后接动词原形。"},{"q":"Let's 的意思是？","options":["让我","让我们","使他","让你们"],"answer":"让我们","explain":"Let's = Let us，让我们。"}]},
  {"id":"plural-irregular","title":"名词复数特殊变化","explain":"有些名词变复数不按规则：单复同形（sheep→sheep）、oo 变 ee（foot→feet, tooth→teeth）、或特殊变化（mouse→mice, goose→geese）。","rules":["单复同形：sheep/deer/fish","oo→ee：foot→feet, tooth→teeth","mouse→mice, goose→geese","child→children, man→men"],"examples":[{"en":"two sheep","cn":"两只羊"},{"en":"two teeth","cn":"两颗牙"}],"quiz":[{"q":"tooth 的复数是？","options":["tooths","teeth","toothes","tooth"],"answer":"teeth","explain":"oo 变 ee：tooth→teeth。"},{"q":"sheep 的复数是？","options":["sheeps","sheep","sheepes","sheepies"],"answer":"sheep","explain":"sheep 单复同形。"}]},
  {"id":"comparative-than","title":"比较级 + than","explain":"两者比较用'比较级 + than'（比…更…）。如 taller than me（比我高）。多音节词用 more ... than。","rules":["比较级 + than（taller than）","多音节：more ... than","than 后接比较对象","可与 much/a lot 连用表程度"],"examples":[{"en":"He is taller than his brother.","cn":"他比弟弟高。"},{"en":"This book is more fun than that one.","cn":"这本书比那本更有趣。"}],"quiz":[{"q":"'比我高'是？","options":["tall than me","taller than me","tallest than me","more tall than me"],"answer":"taller than me","explain":"比较级 + than。"},{"q":"'比那本更有趣'用？","options":["interesting than","more interesting than","most interesting than","interestinger than"],"answer":"more interesting than","explain":"多音节用 more ... than。"}]},
  {"id":"how-transport","title":"how 问方式与交通","explain":"how 可问'怎样、如何'。问交通方式用 How do you go ...? 回答用 by + 交通工具（by bus / by bike），或 on foot（步行）。","rules":["How do you go to ...?","by + 交通工具（by car）","步行用 on foot","回答说明方式"],"examples":[{"en":"How do you go to school? By bus.","cn":"你怎么上学？坐公交。"},{"en":"I go home on foot.","cn":"我步行回家。"}],"quiz":[{"q":"'你怎样去学校？'是？","options":["What do you go to school?","How do you go to school?","Where do you go?","When do you go?"],"answer":"How do you go to school?","explain":"问方式用 how。"},{"q":"'坐公交'是？","options":["by bus","on bus","in bus","with bus"],"answer":"by bus","explain":"by + 交通工具。"}]},
  {"id":"need","title":"need（需要）","explain":"need 表示'需要'。作实义动词时后接名词或 to do（I need to eat.）；作情态动词多用于否定/疑问（You needn't go.）。","rules":["need + 名词（I need water.）","need + to do（I need to sleep.）","否定 needn't（不必）","三单 needs"],"examples":[{"en":"I need a pencil.","cn":"我需要一支铅笔。"},{"en":"He needs to rest.","cn":"他需要休息。"}],"quiz":[{"q":"I need ___ (go) home. 填？","options":["go","to go","going","went"],"answer":"to go","explain":"need 后接 to do。"},{"q":"'你不必去'用？","options":["You needn't go.","You don't need go.","You no need go.","You need not to go."],"answer":"You needn't go.","explain":"needn't 表示不必。"}]},
  {"id":"sentence-types","title":"四大句子种类","explain":"英语句子按用途分四类：陈述句（说事实）、疑问句（提问）、祈使句（命令/请求）、感叹句（表感情）。句末标点各不同。","rules":["陈述句：. （I am happy.）","疑问句：? （Are you happy?）","祈使句：. 或 !（Sit down.）","感叹句：! （What a day!）"],"examples":[{"en":"It is sunny. (陈述)","cn":"天气晴朗。"},{"en":"What a nice day! (感叹)","cn":"多好的一天！"}],"quiz":[{"q":"'Are you OK?' 是？","options":["陈述句","疑问句","祈使句","感叹句"],"answer":"疑问句","explain":"以问号结尾、提问的是疑问句。"},{"q":"'Sit down, please.' 是？","options":["陈述句","疑问句","祈使句","感叹句"],"answer":"祈使句","explain":"表示请求/命令的是祈使句。"}]},
  {"id":"tenses-overview","title":"六大时态总览","explain":"小学常见六种时态：一般现在、现在进行、一般过去、过去进行、一般将来、现在完成。记住结构和标志词，见到时间词就能判断。","rules":["一般现在：do/does（often, usually）","现在进行：am/is/are+ing（now）","一般过去：did/-ed（yesterday）","过去进行：was/were+ing","一般将来：will/be going to（tomorrow）","现在完成：have/has+done（already, yet）"],"examples":[{"en":"He plays football every day.","cn":"他每天踢球。（一般现在）"},{"en":"She is reading now.","cn":"她正在读。（现在进行）"}],"quiz":[{"q":"见到 now，用哪种时态？","options":["一般现在","现在进行","一般过去","一般将来"],"answer":"现在进行","explain":"now 是现在进行时的标志词。"},{"q":"见到 yesterday，用？","options":["一般现在","现在进行","一般过去","现在完成"],"answer":"一般过去","explain":"yesterday 是一般过去时标志。"}]},
  {"id":"there-be-vs-have","title":"there be 与 have 的区别","explain":"都表示'有'，但不同：there be 强调'某地有某物'（客观存在）；have/has 强调'某人有某物'（所属关系）。","rules":["there be：某地有（There is a book on the desk.）","have/has：某人有（I have a book.）","there be 就近原则","have 用于 I/you/we/they，has 用于三单"],"examples":[{"en":"There is a cat in the room.","cn":"房间里有一只猫。（存在）"},{"en":"I have a cat.","cn":"我有一只猫。（拥有）"}],"quiz":[{"q":"'桌上有一本书'用？","options":["There is","I have","He has","They have"],"answer":"There is","explain":"某地存在用 there be。"},{"q":"'我有一只狗'用？","options":["There is","There are","I have","It has"],"answer":"I have","explain":"所属关系用 have/has。"}]},
  {"id":"colors","title":"颜色词汇","explain":"常见颜色：red 红、blue 蓝、yellow 黄、green 绿、orange 橙、purple 紫、pink 粉、black 黑、white 白、brown 棕。","rules":["red 红 / blue 蓝 / yellow 黄","green 绿 / orange 橙 / purple 紫","pink 粉 / black 黑 / white 白","brown 棕 / gray 灰"],"examples":[{"en":"I like the red apple.","cn":"我喜欢那个红苹果。"},{"en":"Her dress is blue.","cn":"她的裙子是蓝色的。"}],"quiz":[{"q":"'蓝色'是？","options":["red","blue","green","black"],"answer":"blue","explain":"blue 是蓝色。"},{"q":"'黄色'是？","options":["yellow","orange","purple","pink"],"answer":"yellow","explain":"yellow 是黄色。"}]},
  {"id":"food","title":"食物词汇","explain":"常见食物：rice 米饭、noodles 面条、bread 面包、egg 蛋、meat 肉、fish 鱼、apple 苹果、banana 香蕉、milk 牛奶、water 水。","rules":["rice 米饭 / noodles 面条","bread 面包 / egg 蛋","meat 肉 / fish 鱼","apple 苹果 / banana 香蕉 / milk 牛奶"],"examples":[{"en":"I eat rice and fish.","cn":"我吃米饭和鱼。"},{"en":"She drinks milk.","cn":"她喝牛奶。"}],"quiz":[{"q":"'米饭'是？","options":["rice","bread","noodles","meat"],"answer":"rice","explain":"rice 是米饭。"},{"q":"'香蕉'是？","options":["apple","banana","orange","pear"],"answer":"banana","explain":"banana 是香蕉。"}]},
  {"id":"clothes","title":"衣服词汇","explain":"常见衣物：coat 外套、shirt 衬衫、dress 连衣裙、skirt 短裙、pants 裤子、shoes 鞋、hat 帽子、sweater 毛衣、sock 袜子、jacket 夹克。","rules":["coat 外套 / jacket 夹克","shirt 衬衫 / sweater 毛衣","dress 连衣裙 / skirt 短裙","pants 裤子 / shoes 鞋 / hat 帽子"],"examples":[{"en":"She wears a red dress.","cn":"她穿一条红连衣裙。"},{"en":"My sweater is warm.","cn":"我的毛衣很暖和。"}],"quiz":[{"q":"'毛衣'是？","options":["coat","sweater","shirt","jacket"],"answer":"sweater","explain":"sweater 是毛衣。"},{"q":"'连衣裙'是？","options":["skirt","dress","coat","shirt"],"answer":"dress","explain":"dress 是连衣裙。"}]},
  {"id":"family","title":"家庭成员","explain":"家人称呼：father 爸爸、mother 妈妈、grandfather 爷爷、grandmother 奶奶、brother 兄弟、sister 姐妹、uncle 叔叔、aunt 阿姨、cousin 表亲。","rules":["father 爸爸 / mother 妈妈","grandfather 爷爷 / grandmother 奶奶","brother 兄弟 / sister 姐妹","uncle 叔叔 / aunt 阿姨"],"examples":[{"en":"This is my father.","cn":"这是我爸爸。"},{"en":"I love my grandmother.","cn":"我爱我的奶奶。"}],"quiz":[{"q":"'妈妈'是？","options":["father","mother","sister","aunt"],"answer":"mother","explain":"mother 是妈妈。"},{"q":"'兄弟'是？","options":["brother","sister","cousin","uncle"],"answer":"brother","explain":"brother 是兄弟。"}]},
  {"id":"weather","title":"天气词汇","explain":"天气说法：sunny 晴朗、rainy 下雨、cloudy 多云、windy 有风、snowy 下雪、hot 热、cold 冷、warm 暖、cool 凉。","rules":["sunny 晴 / rainy 雨 / cloudy 云","windy 风 / snowy 雪","hot 热 / cold 冷","warm 暖 / cool 凉"],"examples":[{"en":"It is sunny today.","cn":"今天晴朗。"},{"en":"It is cold in winter.","cn":"冬天很冷。"}],"quiz":[{"q":"'下雨的'是？","options":["sunny","rainy","cloudy","windy"],"answer":"rainy","explain":"rainy 是下雨的。"},{"q":"'热的'是？","options":["hot","cold","warm","cool"],"answer":"hot","explain":"hot 是热的。"}]},
  {"id":"school-things","title":"学习用品","explain":"文具用品：book 书、pen 钢笔、pencil 铅笔、ruler 尺子、eraser 橡皮、bag 书包、desk 书桌、chair 椅子、crayon 蜡笔、knife 小刀。","rules":["book 书 / bag 书包","pen 钢笔 / pencil 铅笔","ruler 尺子 / eraser 橡皮","desk 书桌 / chair 椅子"],"examples":[{"en":"I have a new pencil.","cn":"我有一支新铅笔。"},{"en":"The book is on the desk.","cn":"书在书桌上。"}],"quiz":[{"q":"'铅笔'是？","options":["pen","pencil","ruler","eraser"],"answer":"pencil","explain":"pencil 是铅笔。"},{"q":"'橡皮'是？","options":["ruler","eraser","knife","crayon"],"answer":"eraser","explain":"eraser 是橡皮。"}]},
  {"id":"animals","title":"动物词汇","explain":"常见动物：cat 猫、dog 狗、pig 猪、duck 鸭、chicken 鸡、fish 鱼、bird 鸟、rabbit 兔、tiger 老虎、panda 熊猫。","rules":["cat 猫 / dog 狗 / pig 猪","duck 鸭 / chicken 鸡","fish 鱼 / bird 鸟","rabbit 兔 / tiger 虎 / panda 熊猫"],"examples":[{"en":"The cat is cute.","cn":"这只猫很可爱。"},{"en":"I like pandas.","cn":"我喜欢熊猫。"}],"quiz":[{"q":"'熊猫'是？","options":["tiger","panda","rabbit","duck"],"answer":"panda","explain":"panda 是熊猫。"},{"q":"'兔子'是？","options":["bird","fish","rabbit","chicken"],"answer":"rabbit","explain":"rabbit 是兔子。"}]},
  {"id":"festivals","title":"节日词汇","explain":"中外节日：Spring Festival 春节、Mid-Autumn Festival 中秋、National Day 国庆、Christmas 圣诞、New Year 新年、Children's Day 儿童节、birthday 生日。","rules":["Spring Festival 春节","Mid-Autumn Festival 中秋","Christmas 圣诞节","Children's Day 儿童节 / birthday 生日"],"examples":[{"en":"We eat mooncakes at Mid-Autumn Festival.","cn":"中秋我们吃月饼。"},{"en":"Merry Christmas!","cn":"圣诞快乐！"}],"quiz":[{"q":"'中秋节'是？","options":["Spring Festival","Mid-Autumn Festival","Christmas","National Day"],"answer":"Mid-Autumn Festival","explain":"Mid-Autumn Festival 是中秋节。"},{"q":"'圣诞节'是？","options":["Christmas","New Year","birthday","Children's Day"],"answer":"Christmas","explain":"Christmas 是圣诞节。"}]},
  {"id":"body-parts","title":"身体部位","explain":"身体部位：head 头、eye 眼睛、ear 耳朵、nose 鼻子、mouth 嘴、hand 手、foot 脚、arm 手臂、leg 腿、hair 头发。","rules":["head 头 / eye 眼睛 / ear 耳朵","nose 鼻子 / mouth 嘴","hand 手 / foot 脚","arm 手臂 / leg 腿 / hair 头发"],"examples":[{"en":"I have two hands.","cn":"我有两只手。"},{"en":"My eyes are big.","cn":"我的眼睛很大。"}],"quiz":[{"q":"'眼睛'是？","options":["eye","ear","nose","mouth"],"answer":"eye","explain":"eye 是眼睛。"},{"q":"'脚'是？","options":["hand","foot","arm","leg"],"answer":"foot","explain":"foot 是脚（复数 feet）。"}]},
  {"id":"months-seasons","title":"月份与季节","explain":"四季：spring 春、summer 夏、autumn/fall 秋、winter 冬。月份如 January 一月、July 七月、December 十二月，首字母都要大写。","rules":["spring 春 / summer 夏","autumn(=fall) 秋 / winter 冬","月份首字母大写","January 一月 / December 十二月"],"examples":[{"en":"Winter is cold.","cn":"冬天很冷。"},{"en":"My birthday is in July.","cn":"我的生日在七月。"}],"quiz":[{"q":"'夏天'是？","options":["spring","summer","autumn","winter"],"answer":"summer","explain":"summer 是夏天。"},{"q":"'冬天'是？","options":["spring","summer","autumn","winter"],"answer":"winter","explain":"winter 是冬天。"}]}
,
    {"id":"date-expression","title":"英语日期表达","explain":"英语日期顺序常为“月、日、年”（美式）或“日、月、年”（英式）。日要用序数词（1st, 2nd, 3rd, 4th…），星期与月份首字母都要大写。","rules":["美式：月 日 年（July 1st, 2026）","英式：日 月 年（1st July, 2026）","日期用序数词：1st / 2nd / 3rd / 4th","星期、月份首字母大写"],"examples":[{"en":"Today is July 1st.","cn":"今天是七月一日。"},{"en":"My birthday is on May 5th.","cn":"我的生日在五月五日。"}],"quiz":[{"q":"日期 3 号应写成？","options":["3th","3rd","3st","3nd"],"answer":"3rd","explain":"3 的序数词是 3rd。"},{"q":"星期几首字母要？","options":["小写","大写","不用大写","随便"],"answer":"大写","explain":"Monday 等星期名词首字母必须大写。"}]},
    {"id":"greetings","title":"日常问候与介绍","explain":"见面用 Hello / Hi 打招呼；问好用 How are you?，常见回答 I'm fine, thank you. 介绍自己用 I am… / My name is…，初次见面说 Nice to meet you.","rules":["Hello / Hi 打招呼","How are you? 问好","I'm… / My name is… 介绍自己","Nice to meet you. 很高兴认识你"],"examples":[{"en":"Hello, I am Tom.","cn":"你好，我是汤姆。"},{"en":"Nice to meet you!","cn":"很高兴认识你！"}],"quiz":[{"q":"对方说 Nice to meet you.，你回应？","options":["Hello.","Nice to meet you, too.","Goodbye.","Sorry."],"answer":"Nice to meet you, too.","explain":"用 too 回应表示“我也很高兴认识你”。"},{"q":"介绍自己名字用？","options":["I am…","You are…","He is…","She is…"],"answer":"I am…","explain":"介绍自己用 I am 或 My name is。"}]},
    {"id":"shopping","title":"购物用语","explain":"购物时店员常说 Can I help you?（我能帮你吗）；问价格用 How much is it? 觉得合适可说 I'll take it.（我要买它），太贵可说 That's too expensive.","rules":["Can I help you? 我能帮你吗","How much is it? 多少钱","I'll take it. 我要买它","That's too expensive. 太贵了"],"examples":[{"en":"How much is the toy?","cn":"这个玩具多少钱？"},{"en":"I'll take it.","cn":"我要买下它。"}],"quiz":[{"q":"问价格用？","options":["How many?","How much?","How old?","What time?"],"answer":"How much?","explain":"问价格用 How much。"},{"q":"店员招呼顾客常说？","options":["Goodbye.","Can I help you?","I'm sorry.","Sit down."],"answer":"Can I help you?","explain":"店员常用 Can I help you? 招呼顾客。"}]},
    {"id":"asking-way","title":"问路与方位","explain":"问路用 Where is…? / How can I get to…? 指路用 Go straight.（直走）、Turn left / right.（左转 / 右转）、It's next to…（在…旁边）。","rules":["Where is…? 在哪里","Go straight. 直走","Turn left / right. 左转 / 右转","It's next to… 在…旁边"],"examples":[{"en":"Excuse me, where is the school?","cn":"请问学校在哪里？"},{"en":"Turn left at the corner.","cn":"在拐角处左转。"}],"quiz":[{"q":"指路“直走”用？","options":["Go straight.","Turn left.","Sit down.","Come here."],"answer":"Go straight.","explain":"Go straight 表示直走。"},{"q":"问“图书馆在哪里”用？","options":["Where is the library?","What is the library?","Who is the library?","How is the library?"],"answer":"Where is the library?","explain":"问地点用 Where is。"}]},
    {"id":"ing-spelling","title":"动词 -ing 拼写规则","explain":"现在分词 / 动名词在动词后加 -ing。拼写有规则：一般直接加；以不发音 e 结尾去 e 加 -ing；重读闭音节辅元辅结尾要双写尾字母；以 ie 结尾变 y 再加 -ing。","rules":["一般直接加 -ing（play → playing）","去 e 加 -ing（make → making）","辅元辅双写（run → running, swim → swimming）","ie 变 y（lie → lying）"],"examples":[{"en":"reading","cn":"读（read + ing）"},{"en":"making","cn":"制作（make 去 e + ing）"}],"quiz":[{"q":"make 的 -ing 形式是？","options":["makeing","making","maked","makking"],"answer":"making","explain":"以不发音 e 结尾，去 e 加 -ing。"},{"q":"run 的 -ing 形式是？","options":["runing","running","runned","runing"],"answer":"running","explain":"重读闭音节辅元辅结尾，双写 n 加 -ing。"}]},
    {"id":"s-spelling","title":"三单 -s 拼写规则","explain":"一般现在时中，he / she / it 作主语时动词加 -s 或 -es。以 s / x / ch / sh / o 结尾加 -es；辅音 + y 结尾变 y 为 i 加 -es；其余加 -s；have 变 has。","rules":["一般加 -s（like → likes）","s / x / ch / sh / o 加 -es（watch → watches, go → goes）","辅音 + y 变 y 为 i 加 -es（study → studies）","have 变 has（不规则）"],"examples":[{"en":"She likes apples.","cn":"她喜欢苹果。"},{"en":"He goes to school.","cn":"他去上学。"}],"quiz":[{"q":"watch 的三单是？","options":["watchs","watches","watchies","watch"],"answer":"watches","explain":"以 ch 结尾加 -es。"},{"q":"study 的三单是？","options":["studys","studies","studyies","studyes"],"answer":"studies","explain":"辅音 + y 变 y 为 i 再加 -es。"}]},
    {"id":"weather-sentence","title":"天气问答句型","explain":"问天气用 What's the weather like? 或 How's the weather? 回答用 It is + 天气形容词：sunny 晴朗、rainy 下雨、windy 有风、cloudy 多云、snowy 下雪、hot / cold 冷热。","rules":["How's the weather? 天气怎样","It is sunny / rainy / windy","It is hot / cold / warm","It is snowing. 正在下雪"],"examples":[{"en":"How's the weather today?","cn":"今天天气怎样？"},{"en":"It is sunny and warm.","cn":"天气晴朗又温暖。"}],"quiz":[{"q":"问天气用？","options":["What's the weather like?","How are you?","What time is it?","Where is it?"],"answer":"What's the weather like?","explain":"用 What's the weather like? 或 How's the weather? 问天气。"},{"q":"“正在下雨”说？","options":["It is rain.","It is raining.","It rains.","It rain."],"answer":"It is raining.","explain":"用 be + 动词 -ing 表示正在下雨。"}]},
    {"id":"politeness","title":"道歉与感谢","explain":"道歉用 I'm sorry.；要打扰别人先用 Excuse me.。感谢用 Thank you. / Thanks.，回应感谢用 You're welcome.（不客气）。","rules":["Thank you. / Thanks. 谢谢","You're welcome. 不客气","I'm sorry. 对不起","Excuse me. 打扰了 / 借过"],"examples":[{"en":"Thank you for your help.","cn":"谢谢你的帮助。"},{"en":"You're welcome.","cn":"不客气。"}],"quiz":[{"q":"别人说 Thank you.，你回应？","options":["Thank you.","You're welcome.","Sorry.","Excuse me."],"answer":"You're welcome.","explain":"感谢的回应是 You're welcome。"},{"q":"要打扰别人前先说？","options":["Hello.","Excuse me.","Goodbye.","Sorry."],"answer":"Excuse me.","explain":"Excuse me. 用于引起注意或借过。"}]},
    {"id":"was-were","title":"be 动词过去式（was / were）","explain":"说过去的情况要用 be 动词的过去式。was 用于 I / he / she / it 和单数名词；were 用于 you / we / they 和复数名词。否定直接在后面加 not。","rules":["I / he / she / it + was","you / we / they + were","否定：was not (wasn't) / were not (weren't)","疑问：把 was / were 提到句首"],"examples":[{"en":"I was at home yesterday.","cn":"我昨天在家。"},{"en":"They were very happy.","cn":"他们当时很开心。"},{"en":"She wasn't late for school.","cn":"她上学没有迟到。"}],"quiz":[{"q":"They ___ in the park last Sunday.","options":["was","were","is","are"],"answer":"were","explain":"they 是复数，过去式用 were。"},{"q":"I ___ ten years old last year.","options":["were","was","am","be"],"answer":"was","explain":"I 的 be 动词过去式用 was。"},{"q":"He ___ not at school yesterday.","options":["were","was","are","do"],"answer":"was","explain":"he 是单数，过去式用 was，否定加 not。"}]},
    {"id":"do-does","title":"助动词 do 与 does","explain":"一般现在时的否定句和疑问句要借助 do / does。主语是 he / she / it 或单数名词时用 does，其他情况用 do。用了 does 之后，后面的动词要变回原形。","rules":["I / you / we / they + do","he / she / it + does","否定：don't / doesn't + 动词原形","doesn't 后面动词不再加 -s"],"examples":[{"en":"Do you like milk?","cn":"你喜欢牛奶吗？"},{"en":"She doesn't watch TV at night.","cn":"她晚上不看电视。"},{"en":"Does he play football?","cn":"他踢足球吗？"}],"quiz":[{"q":"___ your sister like apples?","options":["Do","Does","Is","Are"],"answer":"Does","explain":"your sister 是单数第三人称，用 Does。"},{"q":"He ___ like carrots.","options":["don't","doesn't","isn't","not"],"answer":"doesn't","explain":"he 用 doesn't，后面动词用原形 like。"},{"q":"We ___ go to school on Sunday.","options":["doesn't","don't","isn't","aren't"],"answer":"don't","explain":"we 用 don't。"}]},
    {"id":"did-question","title":"过去时的疑问与否定（did）","explain":"一般过去时的疑问句用 Did + 主语 + 动词原形；否定句用 didn't + 动词原形。注意：只要出现了 did / didn't，后面的动词就用原形，不再变过去式。","rules":["Did + 主语 + 动词原形 ?","didn't + 动词原形","回答：Yes, I did. / No, I didn't.","did 已表过去，动词不再加 -ed"],"examples":[{"en":"Did you finish your homework?","cn":"你写完作业了吗？"},{"en":"I didn't see him yesterday.","cn":"我昨天没看见他。"},{"en":"Yes, I did.","cn":"是的，我做了。"}],"quiz":[{"q":"___ you go to the zoo last week?","options":["Do","Did","Are","Was"],"answer":"Did","explain":"last week 表过去，疑问用 Did。"},{"q":"She didn't ___ her book.","options":["brought","brings","bring","bringing"],"answer":"bring","explain":"didn't 后面用动词原形 bring。"},{"q":"“你昨天看电视了吗？”的答语是？","options":["Yes, I do.","Yes, I did.","Yes, I am.","Yes, I was."],"answer":"Yes, I did.","explain":"用 Did 提问，就用 did 回答。"}]},
    {"id":"be-going-to","title":"be going to 表示打算","explain":"be going to 表示“打算、计划要做某事”，也可表示根据现在的情况判断将要发生的事。结构是 am / is / are + going to + 动词原形。","rules":["I am going to…","he / she / it is going to…","you / we / they are going to…","going to 后面一定接动词原形"],"examples":[{"en":"I am going to visit my grandma.","cn":"我打算去看奶奶。"},{"en":"It is going to rain.","cn":"要下雨了。"},{"en":"They are going to play basketball.","cn":"他们打算去打篮球。"}],"quiz":[{"q":"We ___ going to have a picnic.","options":["am","is","are","be"],"answer":"are","explain":"we 后面用 are。"},{"q":"She is going to ___ a new book.","options":["reads","read","reading","readed"],"answer":"read","explain":"going to 后面接动词原形。"},{"q":"Look at the black clouds! It ___ going to rain.","options":["am","is","are","be"],"answer":"is","explain":"It 后面用 is。"}]},
    {"id":"there-was-were","title":"There was / There were","explain":"There be 句型的过去式：单数或不可数名词用 There was；复数名词用 There were。表示“过去某地有某物”。","rules":["There was + 单数 / 不可数名词","There were + 复数名词","否定：There wasn't / weren't","疑问：Was / Were there…?"],"examples":[{"en":"There was a big tree here.","cn":"这里以前有一棵大树。"},{"en":"There were many books on the desk.","cn":"桌上以前有很多书。"},{"en":"There wasn't any milk in the fridge.","cn":"冰箱里当时没有牛奶。"}],"quiz":[{"q":"There ___ two cats in the yard just now.","options":["was","were","is","are"],"answer":"were","explain":"two cats 是复数，用 were。"},{"q":"There ___ some water in the bottle.","options":["were","was","are","have"],"answer":"was","explain":"water 不可数，用 was。"},{"q":"___ there a park near your home before?","options":["Was","Were","Did","Do"],"answer":"Was","explain":"a park 单数，疑问用 Was there。"}]},
    {"id":"ed-spelling","title":"动词过去式 -ed 拼写规则","explain":"规则动词的过去式在词尾加 -ed。拼写有四条规则：一般直接加；以不发音 e 结尾只加 -d；辅音 + y 结尾变 y 为 i 加 -ed；重读闭音节辅元辅结尾要双写末尾字母。","rules":["一般加 -ed（play → played）","以 e 结尾加 -d（like → liked）","辅音 + y 变 i 加 -ed（study → studied）","辅元辅双写（stop → stopped）"],"examples":[{"en":"I played football yesterday.","cn":"我昨天踢了足球。"},{"en":"She studied hard last night.","cn":"她昨晚学习很努力。"},{"en":"The bus stopped here.","cn":"公交车在这里停了。"}],"quiz":[{"q":"like 的过去式是？","options":["likeed","liked","likd","likied"],"answer":"liked","explain":"以不发音 e 结尾，只加 -d。"},{"q":"carry 的过去式是？","options":["carryed","carried","carrid","carryied"],"answer":"carried","explain":"辅音 + y 结尾，变 y 为 i 再加 -ed。"},{"q":"stop 的过去式是？","options":["stoped","stopped","stopd","stopeed"],"answer":"stopped","explain":"重读闭音节辅元辅结尾，双写 p 加 -ed。"}]},
    {"id":"ed-pronunciation","title":"-ed 的三种读音","explain":"过去式 -ed 有三种读音：清辅音后读 /t/，浊辅音和元音后读 /d/，以 t 或 d 结尾的词后读 /ɪd/（多出一个音节）。","rules":["清辅音后读 /t/：worked, helped, watched","浊辅音或元音后读 /d/：played, cleaned, opened","以 /t/ /d/ 结尾后读 /ɪd/：wanted, needed","读 /ɪd/ 时音节会变多"],"examples":[{"en":"I helped my mother.","cn":"我帮了妈妈。（helped 的 ed 读 /t/）"},{"en":"He cleaned the room.","cn":"他打扫了房间。（cleaned 的 ed 读 /d/）"},{"en":"We wanted some water.","cn":"我们当时想要点水。（wanted 的 ed 读 /ɪd/）"}],"quiz":[{"q":"wanted 的 -ed 读什么？","options":["/t/","/d/","/ɪd/","不发音"],"answer":"/ɪd/","explain":"want 以 /t/ 结尾，-ed 读 /ɪd/。"},{"q":"played 的 -ed 读什么？","options":["/t/","/d/","/ɪd/","/s/"],"answer":"/d/","explain":"play 以元音结尾，-ed 读 /d/。"},{"q":"watched 的 -ed 读什么？","options":["/t/","/d/","/ɪd/","/z/"],"answer":"/t/","explain":"watch 以清辅音 /tʃ/ 结尾，-ed 读 /t/。"}]},
    {"id":"adverb-ly","title":"形容词变副词（加 -ly）","explain":"副词用来修饰动词，说明动作怎么做。大多数形容词加 -ly 就变成副词：slow → slowly。以辅音 + y 结尾的把 y 变 i 再加 -ly：happy → happily。","rules":["一般加 -ly（quick → quickly）","辅音 + y 变 i 加 -ly（easy → easily）","以 le 结尾去 e 加 -y（simple → simply）","特殊：good → well，fast → fast"],"examples":[{"en":"He runs quickly.","cn":"他跑得很快。"},{"en":"She sings happily.","cn":"她开心地唱歌。"},{"en":"Please speak slowly.","cn":"请说慢一点。"}],"quiz":[{"q":"careful 的副词形式是？","options":["carefuly","carefully","carefull","carefuling"],"answer":"carefully","explain":"直接加 -ly，注意保留 l。"},{"q":"happy 的副词形式是？","options":["happyly","happily","happyly","happely"],"answer":"happily","explain":"辅音 + y 变 i 再加 -ly。"},{"q":"He writes ___ .（careful）","options":["careful","carefully","carefuler","carefulest"],"answer":"carefully","explain":"修饰动词 writes 要用副词。"}]},
    {"id":"good-well","title":"good 与 well 的区别","explain":"good 是形容词，修饰名词或跟在 be 动词后面；well 是副词，修饰动词，说明做得怎么样。注意 well 也可作形容词表示“身体好”。","rules":["good + 名词：a good student","be + good：You are good.","动词 + well：He swims well.","身体好：I am well now."],"examples":[{"en":"She is a good singer.","cn":"她是一位好歌手。"},{"en":"She sings well.","cn":"她唱得很好。"},{"en":"My English is good.","cn":"我的英语很好。"}],"quiz":[{"q":"He plays basketball ___ .","options":["good","well","goodly","best"],"answer":"well","explain":"修饰动词 plays 要用副词 well。"},{"q":"This is a ___ book.","options":["well","good","goodly","better"],"answer":"good","explain":"修饰名词 book 用形容词 good。"},{"q":"Your handwriting is very ___ .","options":["well","good","wellly","goodly"],"answer":"good","explain":"be 动词后面用形容词 good。"}]},
    {"id":"comparative-more","title":"长形容词的比较级（more / most）","explain":"两个或以上音节的长形容词，比较级在前面加 more，最高级加 the most，不加 -er / -est。","rules":["more + 长形容词 + than","the most + 长形容词","beautiful → more beautiful → the most beautiful","短词仍用 -er / -est：tall → taller"],"examples":[{"en":"This flower is more beautiful than that one.","cn":"这朵花比那朵更美。"},{"en":"He is the most careful student in our class.","cn":"他是我们班最细心的学生。"},{"en":"Maths is more difficult than English for me.","cn":"对我来说数学比英语难。"}],"quiz":[{"q":"interesting 的比较级是？","options":["interestinger","more interesting","most interesting","interestingest"],"answer":"more interesting","explain":"长形容词比较级用 more。"},{"q":"This story is ___ than that one.","options":["excitinger","more exciting","most exciting","exciting"],"answer":"more exciting","explain":"exciting 是长形容词，用 more。"},{"q":"She is ___ girl in the group.","options":["the most friendly","most friendly","more friendly","friendliest most"],"answer":"the most friendly","explain":"最高级前要加 the。"}]},
    {"id":"as-as","title":"as … as 同级比较","explain":"as + 形容词或副词原级 + as 表示“和……一样……”。否定形式 not as … as 表示“不如……”，形容词不用比较级。","rules":["as + 原级 + as：一样……","not as / so + 原级 + as：不如……","中间放形容词或副词原级","不能用比较级：as taller as ✗"],"examples":[{"en":"Tom is as tall as Jack.","cn":"汤姆和杰克一样高。"},{"en":"She runs as fast as I do.","cn":"她跑得和我一样快。"},{"en":"This book is not as thick as that one.","cn":"这本书不如那本厚。"}],"quiz":[{"q":"He is as ___ as his brother.","options":["stronger","strong","strongest","more strong"],"answer":"strong","explain":"as … as 中间用原级。"},{"q":"“我的书包和你的一样新”译作？","options":["My bag is as new as yours.","My bag is as newer as yours.","My bag is newer as yours.","My bag is as new than yours."],"answer":"My bag is as new as yours.","explain":"as + 原级 + as。"},{"q":"This room is not ___ big as that one.","options":["so","very","more","most"],"answer":"so","explain":"否定可用 not so … as 或 not as … as。"}]},
    {"id":"object-pronoun","title":"宾格代词（me / him / her / us / them）","explain":"代词作动词或介词的宾语时要用宾格：I→me，he→him，she→her，we→us，they→them，you 和 it 形式不变。","rules":["动词后面用宾格：Help me.","介词后面用宾格：with him","主格作主语，宾格作宾语","you / it 主格宾格同形"],"examples":[{"en":"Please help me.","cn":"请帮帮我。"},{"en":"I play with them every day.","cn":"我每天和他们一起玩。"},{"en":"She gives him a gift.","cn":"她送给他一件礼物。"}],"quiz":[{"q":"Can you help ___ ?（I）","options":["I","me","my","mine"],"answer":"me","explain":"help 后面作宾语用宾格 me。"},{"q":"I sit next to ___ .（she）","options":["she","her","hers","herself"],"answer":"her","explain":"介词 to 后面用宾格 her。"},{"q":"The teacher asks ___ a question.（we）","options":["we","us","our","ours"],"answer":"us","explain":"动词后面作宾语用宾格 us。"}]},
    {"id":"apostrophe-s","title":"名词所有格（'s / '）","explain":"表示“某人的”在名词后加 's；如果是以 s 结尾的复数名词，只加一个撇号 '。表示无生命物体的所属常用 of。","rules":["单数名词 + 's：Tom's bag","复数以 s 结尾只加 '：the students' books","不以 s 结尾的复数加 's：children's toys","无生命物体常用 of：the door of the room"],"examples":[{"en":"This is my sister's pencil.","cn":"这是我姐姐的铅笔。"},{"en":"The boys' classroom is big.","cn":"男孩们的教室很大。"},{"en":"It is the children's playground.","cn":"这是孩子们的操场。"}],"quiz":[{"q":"“汤姆的书”译作？","options":["Tom book","Toms book","Tom's book","Tom of book"],"answer":"Tom's book","explain":"单数名词后加 's。"},{"q":"“老师们的办公室”译作？","options":["teachers office","the teachers' office","the teacher's offices","the teachers's office"],"answer":"the teachers' office","explain":"复数以 s 结尾，只加撇号。"},{"q":"“孩子们的玩具”译作？","options":["childrens toys","children toys","the children's toys","the childrens' toys"],"answer":"the children's toys","explain":"children 不以 s 结尾，加 's。"}]},
    {"id":"whose-question","title":"Whose…? 问东西是谁的","explain":"Whose 意思是“谁的”，用来问物品的主人。回答可用名词所有格（Tom's）或名词性物主代词（mine / yours / his / hers / ours / theirs）。","rules":["Whose + 名词 + is / are…?","回答：It's Tom's. / It's mine.","Whose 不要与 who's（who is）混淆","复数用 Whose … are these?"],"examples":[{"en":"Whose book is this?","cn":"这是谁的书？"},{"en":"It's mine.","cn":"是我的。"},{"en":"Whose shoes are those?","cn":"那些是谁的鞋？"}],"quiz":[{"q":"___ pen is this? It's Lily's.","options":["Who","Whose","Who's","Which"],"answer":"Whose","explain":"问“谁的”用 Whose。"},{"q":"Whose bag is it? — It's ___ .（I）","options":["my","me","mine","I"],"answer":"mine","explain":"单独回答用名词性物主代词 mine。"},{"q":"Whose gloves ___ these?","options":["is","are","am","be"],"answer":"are","explain":"gloves 是复数，用 are。"}]},
    {"id":"which-question","title":"Which…? 选择疑问","explain":"Which 表示“哪一个”，在一定范围内选择时使用；What 的范围不限。Which one / Which of… 都很常用。","rules":["Which + 名词：Which colour do you like?","Which one 哪一个","范围明确用 Which，范围不明用 What","回答直接说出所选的那一个"],"examples":[{"en":"Which colour do you like, red or blue?","cn":"你喜欢哪个颜色，红的还是蓝的？"},{"en":"Which one is yours?","cn":"哪一个是你的？"},{"en":"Which season do you like best?","cn":"你最喜欢哪个季节？"}],"quiz":[{"q":"___ do you want, tea or juice?","options":["What","Which","Who","Whose"],"answer":"Which","explain":"在两者之间选择用 Which。"},{"q":"___ is your name?","options":["Which","What","Whose","Where"],"answer":"What","explain":"问名字范围不限，用 What。"},{"q":"Which bag is heavier, this one ___ that one?","options":["and","or","but","so"],"answer":"or","explain":"选择疑问句用 or 连接两个选项。"}]},
    {"id":"why-because","title":"Why…? 与 Because…","explain":"Why 用来问原因，回答用 Because + 句子。Because 不能和 so 同时用在一句话里。","rules":["Why + 助动词 + 主语 + 动词?","回答：Because + 主语 + 动词","Because 后面接完整的句子","不要写成 Because…, so…"],"examples":[{"en":"Why do you like summer?","cn":"你为什么喜欢夏天？"},{"en":"Because I can swim.","cn":"因为我可以游泳。"},{"en":"Why is he late? Because the bus was slow.","cn":"他为什么迟到？因为公交车太慢了。"}],"quiz":[{"q":"___ do you like dogs? Because they are friendly.","options":["What","Why","Who","When"],"answer":"Why","explain":"问原因用 Why。"},{"q":"Why are you happy? — ___ I got a prize.","options":["So","Because","But","And"],"answer":"Because","explain":"回答原因用 Because。"},{"q":"下面哪句正确？","options":["Because it rained, so we stayed home.","Because it rained, we stayed home.","It rained, because we stayed home.","So it rained, because we stayed home."],"answer":"Because it rained, we stayed home.","explain":"because 和 so 不能同时使用。"}]},
    {"id":"if-clause","title":"if 引导的条件句","explain":"if 表示“如果”。当条件很可能发生时，if 从句用一般现在时，主句用将来时（will）或情态动词。注意 if 从句里不用 will。","rules":["if + 一般现在时，主句用 will","if 从句在前要用逗号隔开","if 从句里不用 will","也可用 can / must 等情态动词"],"examples":[{"en":"If it rains, we will stay at home.","cn":"如果下雨，我们就待在家里。"},{"en":"If you study hard, you will pass the test.","cn":"如果你努力学习，你就会通过测试。"},{"en":"We can go out if the weather is fine.","cn":"如果天气好，我们就可以出去。"}],"quiz":[{"q":"If it ___ tomorrow, we will not go.","options":["will rain","rains","rained","raining"],"answer":"rains","explain":"if 从句用一般现在时。"},{"q":"If you get up early, you ___ catch the bus.","options":["will","are","do","did"],"answer":"will","explain":"主句用 will + 动词原形。"},{"q":"下面哪句正确？","options":["If he will come, I will be happy.","If he comes, I will be happy.","If he come, I will be happy.","If he came, I will be happy."],"answer":"If he comes, I will be happy.","explain":"if 从句用一般现在时，第三人称加 -s。"}]},
    {"id":"when-clause","title":"when 引导的时间状语从句","explain":"when 意思是“当……的时候”，引导时间状语从句。从句放句首时要用逗号；主句和从句的时态要前后一致。","rules":["When + 主语 + 动词, 主句","主句在前不用逗号","过去的事，两边都用过去式","将来的事，when 从句用现在时"],"examples":[{"en":"When I was six, I started school.","cn":"我六岁时开始上学。"},{"en":"I will call you when I get home.","cn":"我到家就给你打电话。"},{"en":"She sings when she is happy.","cn":"她开心的时候就唱歌。"}],"quiz":[{"q":"When I ___ young, I liked cartoons.","options":["am","was","were","be"],"answer":"was","explain":"讲过去的事，I 用 was。"},{"q":"I will tell him when he ___ back.","options":["will come","comes","came","coming"],"answer":"comes","explain":"when 从句表将来用现在时。"},{"q":"When it rained, we ___ inside.","options":["stay","stays","stayed","will stay"],"answer":"stayed","explain":"从句是过去式，主句也用过去式。"}]},
    {"id":"like-doing","title":"like / enjoy + 动词 -ing","explain":"表达喜欢做某事，可以说 like doing 或 like to do；enjoy 后面只能接动词 -ing 形式，不能接 to do。","rules":["like doing = like to do","enjoy + doing（不能 enjoy to do）","be good at + doing","How about + doing?"],"examples":[{"en":"I like swimming in summer.","cn":"我喜欢在夏天游泳。"},{"en":"She enjoys reading stories.","cn":"她喜欢读故事。"},{"en":"He is good at drawing.","cn":"他擅长画画。"}],"quiz":[{"q":"I enjoy ___ music.","options":["listen","to listen","listening","listens"],"answer":"listening","explain":"enjoy 后面接动词 -ing。"},{"q":"She likes ___ pictures.","options":["draw","drawing","draws","drew"],"answer":"drawing","explain":"like doing 表示喜欢做某事。"},{"q":"He is good at ___ football.","options":["play","plays","playing","played"],"answer":"playing","explain":"at 是介词，后面接 -ing。"}]},
    {"id":"a-few-a-little","title":"a few 与 a little","explain":"a few 修饰可数名词复数，表示“几个”；a little 修饰不可数名词，表示“一点”。去掉 a 变成 few / little 时，意思变成“几乎没有”。","rules":["a few + 可数名词复数","a little + 不可数名词","few / little 表示“几乎没有”","few 用于可数，little 用于不可数"],"examples":[{"en":"I have a few friends here.","cn":"我在这里有几个朋友。"},{"en":"There is a little water in the cup.","cn":"杯子里有一点水。"},{"en":"He has few books.","cn":"他几乎没有书。"}],"quiz":[{"q":"There are ___ apples on the table.","options":["a little","a few","much","a lot"],"answer":"a few","explain":"apples 可数复数，用 a few。"},{"q":"Add ___ salt, please.","options":["a few","a little","many","few"],"answer":"a little","explain":"salt 不可数，用 a little。"},{"q":"He has ___ money, so he can't buy it.","options":["a little","little","a few","few"],"answer":"little","explain":"little 表示几乎没有，money 不可数。"}]},
    {"id":"measure-words","title":"不可数名词的量词表达","explain":"不可数名词不能直接加数字，要借助量词：a glass of water、a piece of paper、a bottle of milk。数量变多时量词变复数：two glasses of water。","rules":["a glass / cup of + 液体","a piece of + paper / bread / news","a bottle / bowl / bag of + 食物","量词变复数：two pieces of…"],"examples":[{"en":"I want a glass of water.","cn":"我想要一杯水。"},{"en":"She eats two pieces of bread.","cn":"她吃了两片面包。"},{"en":"Give me a bottle of milk, please.","cn":"请给我一瓶牛奶。"}],"quiz":[{"q":"“两杯茶”译作？","options":["two tea","two teas","two cups of tea","two cup of teas"],"answer":"two cups of tea","explain":"量词变复数，tea 保持原形。"},{"q":"I need a ___ of paper.","options":["piece","pieces","bottle","glass"],"answer":"piece","explain":"paper 用 a piece of。"},{"q":"He drinks three ___ of milk every day.","options":["bottle","bottles","bottle's","bottled"],"answer":"bottles","explain":"three 后面量词用复数。"}]},
    {"id":"too-either","title":"too 与 either 表示“也”","explain":"too 用在肯定句末尾表示“也”；either 用在否定句末尾表示“也不”。两者前面常加逗号。","rules":["肯定句末：…, too.","否定句末：…, either.","also 多放在句中","Me too. / Me neither. 是口语说法"],"examples":[{"en":"I like ice cream, too.","cn":"我也喜欢冰淇淋。"},{"en":"He doesn't like it, either.","cn":"他也不喜欢它。"},{"en":"She is also a good student.","cn":"她也是个好学生。"}],"quiz":[{"q":"I don't want to go, ___ .","options":["too","either","also","neither"],"answer":"either","explain":"否定句末用 either。"},{"q":"My brother likes football, ___ .","options":["either","too","neither","also"],"answer":"too","explain":"肯定句末用 too。"},{"q":"She can swim, and I can swim ___ .","options":["either","too","neither","not"],"answer":"too","explain":"肯定句用 too。"}]},
    {"id":"very-too","title":"very 与 too 的区别","explain":"very 表示“很”，只是程度高；too 表示“太……了”，含有“超过了合适程度、不好”的意思。","rules":["very + 形容词：很……","too + 形容词：太……（不好）","too … to do：太……而不能做","very 不含负面意思"],"examples":[{"en":"The soup is very hot, but I like it.","cn":"这汤很烫，但我喜欢。"},{"en":"The soup is too hot. I can't drink it.","cn":"这汤太烫了，我喝不了。"},{"en":"He is too young to go to school.","cn":"他太小了，还不能上学。"}],"quiz":[{"q":"这句表示“不好”的是？","options":["The bag is very heavy, but I can carry it.","The bag is too heavy. I can't carry it.","The bag is very new.","The bag is very nice."],"answer":"The bag is too heavy. I can't carry it.","explain":"too 含有“超出承受”的负面意思。"},{"q":"It is ___ cold to swim today.","options":["very","too","so much","many"],"answer":"too","explain":"too … to do 表示太……而不能。"},{"q":"This film is ___ interesting.","options":["too","very","much","many"],"answer":"very","explain":"表示“很有趣”用 very。"}]},
    {"id":"no-not","title":"no 与 not 的区别","explain":"not 是副词，用来否定动词，常与 be / do / can 连用；no 是限定词，直接放在名词前，表示“没有”。","rules":["not 否定动词：I am not…","no + 名词：There is no water.","no = not any","回答问题时 No, … 用于句首"],"examples":[{"en":"I am not tired.","cn":"我不累。"},{"en":"There is no milk in the fridge.","cn":"冰箱里没有牛奶。"},{"en":"No, I don't like it.","cn":"不，我不喜欢它。"}],"quiz":[{"q":"There is ___ bread on the plate.","options":["not","no","don't","isn't"],"answer":"no","explain":"名词前用 no。"},{"q":"She is ___ at home now.","options":["no","not","don't","doesn't"],"answer":"not","explain":"否定 be 动词用 not。"},{"q":"“教室里没有学生”译作？","options":["There are no students in the classroom.","There are not students in the classroom.","There is no student in the classrooms.","There aren't student in the classroom."],"answer":"There are no students in the classroom.","explain":"no + 名词复数表示“没有”。"}]},
    {"id":"time-signal-words","title":"用时间标志词判断时态","explain":"句子里的时间词是判断时态的重要线索：every day / usually 用一般现在时；yesterday / last… / ago 用一般过去时；now / look! 用现在进行时；tomorrow / next… 用将来时。","rules":["every day / often → 一般现在时","yesterday / last week / ago → 一般过去时","now / at the moment / Look! → 现在进行时","tomorrow / next week → will / be going to"],"examples":[{"en":"I go to school every day.","cn":"我每天去上学。"},{"en":"He went to Beijing last year.","cn":"他去年去了北京。"},{"en":"Look! They are running.","cn":"看！他们正在跑。"}],"quiz":[{"q":"He ___ TV last night.","options":["watches","watched","is watching","will watch"],"answer":"watched","explain":"last night 表过去，用过去式。"},{"q":"Listen! She ___ a song.","options":["sings","sang","is singing","will sing"],"answer":"is singing","explain":"Listen! 提示正在进行。"},{"q":"We ___ a party next Sunday.","options":["have","had","are having","will have"],"answer":"will have","explain":"next Sunday 表将来。"}]},
    {"id":"everyone-everything","title":"不定代词作单数主语","explain":"everyone / everybody / everything / nobody / something 等不定代词作主语时，看作单数，动词用第三人称单数形式。","rules":["everyone / everybody + 单数动词","everything / nothing + 单数动词","Everyone is here. ✓","形容词放在不定代词后面：something new"],"examples":[{"en":"Everyone is happy today.","cn":"今天大家都很开心。"},{"en":"Everything looks new.","cn":"一切看起来都很新。"},{"en":"Nobody knows the answer.","cn":"没有人知道答案。"}],"quiz":[{"q":"Everyone ___ ready.","options":["are","is","were","am"],"answer":"is","explain":"everyone 作单数，用 is。"},{"q":"Everything ___ fine now.","options":["are","is","have","were"],"answer":"is","explain":"everything 作单数。"},{"q":"Nobody ___ late this morning.","options":["are","was","were","have"],"answer":"was","explain":"nobody 作单数，过去式用 was。"}]},
    {"id":"look-see-watch","title":"look / see / watch 的区别","explain":"look 强调“看的动作”，常跟 at；see 强调“看见的结果”；watch 指“注视、观看”会动的东西，如比赛、电视。","rules":["look at + 物：看某物","see 看见（结果）","watch 观看（会动的画面）","read a book 不用 see / watch"],"examples":[{"en":"Look at the blackboard, please.","cn":"请看黑板。"},{"en":"I can see a bird in the tree.","cn":"我能看见树上有只鸟。"},{"en":"We watch TV after dinner.","cn":"我们晚饭后看电视。"}],"quiz":[{"q":"___ at me, please.","options":["See","Look","Watch","Read"],"answer":"Look","explain":"look at 表示看的动作。"},{"q":"I can ___ a plane in the sky.","options":["look","see","watch","read"],"answer":"see","explain":"看见的结果用 see。"},{"q":"They ___ a football game now.","options":["look","see","are watching","read"],"answer":"are watching","explain":"观看比赛用 watch。"}]},
    {"id":"say-tell-speak-talk","title":"say / tell / speak / talk 的区别","explain":"say 强调说的内容；tell 后面要接听话的人（tell sb sth）；speak 后面常接语言；talk 表示交谈，常与 to / with / about 连用。","rules":["say + 内容：say hello","tell + 人 + 内容：tell me a story","speak + 语言：speak English","talk to / with sb about sth"],"examples":[{"en":"Please tell me the truth.","cn":"请告诉我真相。"},{"en":"She can speak Chinese and English.","cn":"她会说汉语和英语。"},{"en":"I want to talk with you about it.","cn":"我想和你谈谈这件事。"}],"quiz":[{"q":"Can you ___ me your name?","options":["say","tell","speak","talk"],"answer":"tell","explain":"tell 后面接人，tell me。"},{"q":"He can ___ three languages.","options":["say","tell","speak","talk"],"answer":"speak","explain":"speak + 语言。"},{"q":"They are ___ about the film.","options":["saying","telling","speaking","talking"],"answer":"talking","explain":"talk about 表示谈论。"}]},
    {"id":"borrow-lend","title":"borrow 与 lend 的区别","explain":"borrow 是“借入”，方向是拿进来，用 borrow sth from sb；lend 是“借出”，方向是给出去，用 lend sb sth 或 lend sth to sb。","rules":["borrow sth from sb 从某人借来","lend sb sth 把某物借给某人","lend sth to sb 同上","keep 表示借用一段时间"],"examples":[{"en":"May I borrow your ruler?","cn":"我可以借用你的尺子吗？"},{"en":"I borrowed a book from the library.","cn":"我从图书馆借了一本书。"},{"en":"Can you lend me your pen?","cn":"你能把钢笔借给我吗？"}],"quiz":[{"q":"I want to ___ a book from you.","options":["lend","borrow","keep","give"],"answer":"borrow","explain":"从别人那里借入用 borrow…from。"},{"q":"Please ___ me your umbrella.","options":["borrow","lend","take","bring"],"answer":"lend","explain":"借给某人用 lend sb sth。"},{"q":"He borrowed a bike ___ his friend.","options":["to","from","for","with"],"answer":"from","explain":"borrow sth from sb。"}]},
    {"id":"bring-take","title":"bring 与 take 的区别","explain":"bring 是“带来”，把东西带到说话人这边；take 是“带走”，把东西从这里拿到别处。方向相反。","rules":["bring 带来（往这边）","take 带走（往那边）","bring sth to sb 给某人带来","take sth away 把某物拿走"],"examples":[{"en":"Please bring your homework tomorrow.","cn":"明天请把作业带来。"},{"en":"Take your umbrella with you.","cn":"把你的伞带走。"},{"en":"He brings me some flowers.","cn":"他给我带来一些花。"}],"quiz":[{"q":"Don't forget to ___ your book here.","options":["take","bring","borrow","lend"],"answer":"bring","explain":"带到这里用 bring。"},{"q":"It is raining. ___ your raincoat with you.","options":["Bring","Take","Borrow","Lend"],"answer":"Take","explain":"带走随身用 take。"},{"q":"Mum, please ___ me a glass of water.","options":["take","bring","borrow","lend"],"answer":"bring","explain":"给说话人拿来用 bring。"}]},
    {"id":"listen-hear","title":"listen 与 hear 的区别","explain":"listen 强调“主动去听”的动作，后面接 to；hear 强调“听见”的结果，不用 to。","rules":["listen to + 内容：主动听","hear + 内容：听见（结果）","Listen! 提示正在进行","hear from sb 收到某人的消息"],"examples":[{"en":"I listen to English every morning.","cn":"我每天早上听英语。"},{"en":"I can hear a bird singing.","cn":"我能听见鸟在唱歌。"},{"en":"Listen! Someone is knocking.","cn":"听！有人在敲门。"}],"quiz":[{"q":"She likes to ___ music.","options":["hear","listen","listen to","hear to"],"answer":"listen to","explain":"主动听要用 listen to。"},{"q":"Can you ___ me clearly?","options":["listen","listen to","hear","hearing"],"answer":"hear","explain":"听得见用 hear，不加 to。"},{"q":"___ ! The bell is ringing.","options":["Hear","Listen","Listening","Heard"],"answer":"Listen","explain":"提醒别人注意听用 Listen!"}]},
    {"id":"wear-put-on","title":"wear / put on / in 表示穿着","explain":"wear 表示“穿着”的状态；put on 表示“穿上”的动作；in + 颜色或衣服也可表示穿着。dress 常指给别人穿衣。","rules":["wear 穿着（状态）","put on 穿上（动作）","in + 颜色 / 衣服：穿着…","take off 脱下"],"examples":[{"en":"She wears a red dress today.","cn":"她今天穿着一条红裙子。"},{"en":"Put on your coat. It's cold.","cn":"穿上外套，天冷。"},{"en":"The girl in blue is my sister.","cn":"穿蓝色衣服的女孩是我妹妹。"}],"quiz":[{"q":"It is cold. ___ your hat.","options":["Wear","Put on","In","Take off"],"answer":"Put on","explain":"表示动作“穿上”用 put on。"},{"q":"He always ___ glasses.","options":["puts on","wears","in","takes off"],"answer":"wears","explain":"表示状态“戴着”用 wears。"},{"q":"The boy ___ a white shirt is Tom.","options":["wear","in","put on","wearing on"],"answer":"in","explain":"in + 衣服表示穿着，作定语。"}]},
    {"id":"home-house","title":"home 与 house 的区别","explain":"house 指“房子”这个建筑物；home 指“家”，强调居住和归属。go home 中的 home 是副词，前面不加 to。","rules":["house 房屋（建筑）","home 家（归属）","go home 不加 to","at home 在家"],"examples":[{"en":"Their house is very big.","cn":"他们的房子很大。"},{"en":"I go home at five.","cn":"我五点回家。"},{"en":"My mother is at home now.","cn":"我妈妈现在在家。"}],"quiz":[{"q":"I want to go ___ now.","options":["to home","home","house","to house"],"answer":"home","explain":"go home 中 home 是副词，不加 to。"},{"q":"They built a new ___ near the river.","options":["home","house","homes","at home"],"answer":"house","explain":"指建筑物用 house。"},{"q":"She stays ___ on rainy days.","options":["at home","at house","in home","to home"],"answer":"at home","explain":"“在家”用 at home。"}]},
    {"id":"punctuation","title":"英语标点符号","explain":"陈述句和祈使句用句号（.），疑问句用问号（?），感叹句用感叹号（!）。并列的词之间用逗号（,），最后两项之间用 and。句首字母和 I 都要大写。","rules":["陈述句用句号 .","疑问句用问号 ?","感叹句用感叹号 !","并列用逗号，最后用 and"],"examples":[{"en":"I like apples, bananas and oranges.","cn":"我喜欢苹果、香蕉和橙子。"},{"en":"What a nice day!","cn":"多么好的天气！"},{"en":"Where is my bag?","cn":"我的书包在哪里？"}],"quiz":[{"q":"疑问句结尾用什么标点？","options":["。",".","?","!"],"answer":"?","explain":"英语疑问句用问号 ?。"},{"q":"下面标点正确的是？","options":["I like cats dogs and birds.","I like cats, dogs and birds.","I like cats, dogs, and birds?","I like cats dogs, and birds!"],"answer":"I like cats, dogs and birds.","explain":"并列词间用逗号，最后一项前用 and。"},{"q":"感叹句 What a big dog ___ ","options":[".","?","!",","],"answer":"!","explain":"感叹句用感叹号。"}]},
    {"id":"another-other","title":"another / other / the other","explain":"another 表示“再一个（不确定的）”，后接单数名词；other 后接复数名词；the other 指两者中“另一个”；the others 指“其余的全部”。","rules":["another + 单数名词","other + 复数名词","the other 两者中的另一个","the others = 其余全部"],"examples":[{"en":"May I have another apple?","cn":"我可以再要一个苹果吗？"},{"en":"Some students like maths; other students like art.","cn":"有些学生喜欢数学，有些学生喜欢美术。"},{"en":"I have two pens. One is red, the other is blue.","cn":"我有两支笔，一支红的，另一支蓝的。"}],"quiz":[{"q":"I am still hungry. Give me ___ cake.","options":["other","another","the other","others"],"answer":"another","explain":"再一个（不确定）用 another + 单数。"},{"q":"I have two hands. One is left, ___ is right.","options":["another","other","the other","others"],"answer":"the other","explain":"两者中的另一个用 the other。"},{"q":"Where are ___ students?","options":["another","the other","other","others"],"answer":"the other","explain":"指剩下的那些学生用 the other + 复数。"}]},
    {"id":"each-every","title":"each 与 every","explain":"each 强调“每一个（单独看）”，可用于两个以上；every 强调“每一个（整体看）”，至少三个。两者作主语时动词都用单数。","rules":["each + 单数名词 + 单数动词","every + 单数名词 + 单数动词","each 可指两个，every 至少三个","each of + 复数名词 + 单数动词"],"examples":[{"en":"Each student has a book.","cn":"每个学生都有一本书。"},{"en":"Every child likes candy.","cn":"每个孩子都喜欢糖。"},{"en":"Each of us has a job.","cn":"我们每个人都有一项任务。"}],"quiz":[{"q":"Every boy ___ a school bag.","options":["have","has","having","are"],"answer":"has","explain":"every + 单数名词，动词用单数 has。"},{"q":"___ of my hands is clean.","options":["Every","Each","All","Both"],"answer":"Each","explain":"each of 后接复数，动词用单数。"},{"q":"Each student ___ a different answer.","options":["give","gives","are giving","have"],"answer":"gives","explain":"each + 单数名词作主语，动词用单数。"}]},
    {"id":"interested-interesting","title":"-ed 与 -ing 形容词","explain":"以 -ing 结尾的形容词描述事物本身“令人……的”；以 -ed 结尾的形容词描述人“感到……的”。如 interesting（有趣的事）和 interested（感兴趣的人）。","rules":["-ing 修饰事物：令人…的","-ed 修饰人：感到…的","be interested in 对…感兴趣","exciting / excited、tiring / tired 同理"],"examples":[{"en":"The book is interesting.","cn":"这本书很有趣。"},{"en":"I am interested in science.","cn":"我对科学感兴趣。"},{"en":"The game was exciting, and we were excited.","cn":"比赛很激动人心，我们很兴奋。"}],"quiz":[{"q":"The film is very ___ .","options":["interested","interesting","interest","interests"],"answer":"interesting","explain":"描述事物用 -ing 形容词。"},{"q":"She is ___ in drawing.","options":["interesting","interested","interest","interestingly"],"answer":"interested","explain":"be interested in 表示对…感兴趣。"},{"q":"After the long walk, we felt ___ .","options":["tiring","tired","tire","tires"],"answer":"tired","explain":"人感到累用 tired。"}]},
    {"id":"spend-cost-take","title":"spend / cost / take 表示花费","explain":"spend 的主语是人，spend time / money on sth 或 in doing sth；cost 的主语是物，物 + cost + 钱；take 常用 It takes sb some time to do sth。","rules":["sb spend time / money on sth","sth costs sb some money","It takes sb time to do sth","pay for sth 为某物付款"],"examples":[{"en":"I spend an hour on my homework.","cn":"我花一小时做作业。"},{"en":"The book costs ten yuan.","cn":"这本书要十元。"},{"en":"It takes me ten minutes to walk there.","cn":"我走到那里要十分钟。"}],"quiz":[{"q":"The new bike ___ 500 yuan.","options":["spends","costs","takes","pays"],"answer":"costs","explain":"主语是物，用 cost。"},{"q":"It ___ me twenty minutes to finish it.","options":["spends","costs","takes","pays"],"answer":"takes","explain":"It takes sb time to do sth。"},{"q":"She ___ two hours reading every day.","options":["costs","takes","spends","pays"],"answer":"spends","explain":"主语是人，用 spend。"}]},
    {"id":"already-yet","title":"already 与 yet","explain":"already 表示“已经”，多用于肯定句；yet 表示“还、尚”，多用于否定句和疑问句，常放句末。两者常与现在完成时连用。","rules":["肯定句用 already：已经","否定句用 yet：还没","疑问句用 yet：已经…了吗","yet 通常放在句末"],"examples":[{"en":"I have already finished my homework.","cn":"我已经写完作业了。"},{"en":"He hasn't come yet.","cn":"他还没有来。"},{"en":"Have you had lunch yet?","cn":"你已经吃午饭了吗？"}],"quiz":[{"q":"She hasn't arrived ___ .","options":["already","yet","ever","just"],"answer":"yet","explain":"否定句末用 yet。"},{"q":"I have ___ read this book.","options":["yet","already","never mind","still"],"answer":"already","explain":"肯定句表示“已经”用 already。"},{"q":"Have you cleaned your room ___ ?","options":["already","yet","too","either"],"answer":"yet","explain":"疑问句末常用 yet。"}]},
    {"id":"arrive-reach-get-to","title":"arrive / reach / get to 表示到达","explain":"三个词都表示“到达”。arrive 是不及物动词，大地点用 arrive in，小地点用 arrive at；reach 是及物动词，直接接地点；get to 后面接地点，home / here / there 前不加 to。","rules":["arrive in + 大地点（城市、国家）","arrive at + 小地点（车站、学校）","reach + 地点（及物，不加介词）","get to + 地点；get home / here"],"examples":[{"en":"We arrived in Beijing on Monday.","cn":"我们周一到了北京。"},{"en":"They arrived at the station early.","cn":"他们很早就到了车站。"},{"en":"I get home at six every day.","cn":"我每天六点到家。"}],"quiz":[{"q":"We arrived ___ Shanghai last night.","options":["at","in","to","on"],"answer":"in","explain":"大地点用 arrive in。"},{"q":"He reached ___ the school at eight.","options":["at","in","to","（不填）"],"answer":"（不填）","explain":"reach 是及物动词，后面直接接地点。"},{"q":"What time do you ___ home?","options":["arrive","get to","get","reach to"],"answer":"get","explain":"home 是副词，用 get home，不加 to。"}]}
];;;